  text-decoration: none;
}

.text-link {
  display: inline-flex;
  margin-top: 1rem;
  color: var(--color-accent);
  font-weight: 800;
  text-decoration: none;
}

.button--ghost {
  border-color: rgba(255, 255, 255, 0.72);
  background: transparent;
}

.button--light {
  border-color: #ffffff;
  background: #ffffff;
  color: var(--color-steel);
}

/* The site's CTA pairing, taken from the header: green primary, dark steel
   secondary. Use .button with .button--steel for every two-action row. */
.button--steel {
  border-color: var(--color-steel);
  background: var(--color-steel);
  color: #ffffff;
}

.button--steel:hover,
.button--steel:focus-visible {
  border-color: #004554;
  background: #004554;
  color: #ffffff;
}

.fg-cookie-consent[hidden],
.site-footer__cookie-settings[hidden] {
  display: none;
}

.fg-cookie-consent-open {
  overflow: hidden;
}

.fg-cookie-consent {
  width: min(calc(100% - 2rem), 680px);
  max-width: none;
  max-height: calc(100dvh - 2rem);
  margin: auto;
  padding: 0;
  overflow: auto;
  border: 0;
  border-radius: 20px;
  background: transparent;
  color: var(--color-ink);
  box-shadow:
    0 38px 110px rgba(0, 28, 36, 0.42),
    0 0 0 1px rgba(255, 255, 255, 0.14);
}

.fg-cookie-consent:not([open]) {
  display: none;
}

.fg-cookie-consent::backdrop {
  background:
    radial-gradient(circle at 72% 18%, rgba(46, 172, 102, 0.14), transparent 30%),
    rgba(0, 28, 36, 0.82);
  backdrop-filter: blur(7px) saturate(0.72);
}

.fg-cookie-consent__panel {
  position: relative;
  overflow: hidden;
  padding: clamp(1.6rem, 4vw, 2.35rem);
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-radius: 20px;
  background:
    radial-gradient(circle at 100% 0, rgba(46, 172, 102, 0.1), transparent 31%),
    linear-gradient(155deg, #ffffff 0%, #fbfdfc 58%, #f2f8f6 100%);
}

.fg-cookie-consent__panel::before {
  position: absolute;
  top: 0;
  right: 0;
  left: 0;
  height: 6px;
  background: linear-gradient(90deg, var(--color-steel) 0 28%, var(--color-accent) 28% 100%);
  content: "";
}

.fg-cookie-consent__eyebrow {
  display: flex;
  gap: var(--fg-space-2);
  align-items: center;
  margin: 0 0 0.6rem;
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 850;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.fg-cookie-consent__eyebrow::before {
  width: 9px;
  height: 9px;
  border: 3px solid rgba(46, 172, 102, 0.2);
  border-radius: 50%;
  background: var(--color-accent);
  background-clip: padding-box;
  content: "";
}

.fg-cookie-consent h2 {
  max-width: 560px;
  margin: 0;
  color: var(--color-ink);
  font-size: clamp(1.65rem, 3.4vw, 2.15rem);
  line-height: 1.06;
  letter-spacing: -0.025em;
}

.fg-cookie-consent h2 + p {
  max-width: 590px;
  margin: 0.9rem 0 0;
  color: var(--color-steel);
  font-size: 0.98rem;
  line-height: 1.55;
}

.fg-cookie-consent__note {
  max-width: 590px;
  margin: 0.85rem 0 0;
  padding: 0.72rem 0.85rem;
  border: 1px solid rgba(46, 172, 102, 0.2);
  border-left: 4px solid var(--color-accent);
  border-radius: 10px;
  background: rgba(237, 247, 242, 0.9);
  color: var(--color-steel);
  font-size: var(--fg-text-sm);
  font-weight: 650;
  line-height: 1.42;
}

.fg-cookie-consent__actions {
  display: grid;
  gap: var(--fg-space-3);
  margin-top: 1.25rem;
}

.fg-cookie-consent__actions--three {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.fg-cookie-consent__actions--two {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.fg-cookie-consent .button {
  justify-content: center;
  min-height: 50px;
  padding: 0.78rem 0.9rem;
  border-radius: 10px;
  font-size: 0.94rem;
  box-shadow: 0 10px 24px rgba(0, 45, 58, 0.1);
  text-align: center;
  transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, border-color 160ms ease;
}

.fg-cookie-consent .button:hover,
.fg-cookie-consent .button:focus-visible {
  box-shadow: 0 14px 28px rgba(0, 45, 58, 0.16);
  transform: translateY(-1px);
}

.fg-cookie-consent .button--light {
  border-color: rgba(0, 45, 58, 0.42);
  background: rgba(255, 255, 255, 0.88);
  color: var(--color-ink);
  box-shadow: none;
}

.fg-cookie-consent .button--light:hover,
.fg-cookie-consent .button--light:focus-visible {
  border-color: var(--color-accent);
  background: #e5efee;
  color: var(--color-ink);
}

.fg-cookie-consent__policy {
  margin: 0.95rem 0 0;
  text-align: center;
}

.fg-cookie-consent__policy a {
  color: var(--color-steel);
  font-size: 0.9rem;
  font-weight: 800;
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

.fg-cookie-consent__close {
  position: absolute;
  z-index: 1;
  top: 1rem;
  right: 1rem;
  display: grid;
  width: 40px;
  height: 40px;
  padding: 0;
  place-items: center;
  border: 1px solid rgba(0, 45, 58, 0.18);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.82);
  color: var(--color-ink);
  font-size: 1.4rem;
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 8px 22px rgba(0, 45, 58, 0.1);
  backdrop-filter: blur(8px);
}

.fg-cookie-consent__close[hidden] {
  display: none;
}

.fg-cookie-consent__close:hover,
.fg-cookie-consent__close:focus-visible {
  border-color: var(--color-accent);
  background: #e5efee;
}

.fg-cookie-consent__choices {
  display: grid;
  gap: 0.7rem;
  margin-top: 1.25rem;
}

.fg-cookie-consent__choice {
  display: flex;
  gap: var(--fg-space-4);
  align-items: center;
  justify-content: space-between;
  min-height: 76px;
  padding: 0.9rem 1rem;
  border: 1px solid rgba(0, 45, 58, 0.13);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: 0 8px 22px rgba(0, 45, 58, 0.055);
}

.fg-cookie-consent__choice strong,
.fg-cookie-consent__choice span {
  display: block;
}

.fg-cookie-consent__choice strong {
  color: var(--color-ink);
  font-size: 0.98rem;
  line-height: 1.25;
}

.fg-cookie-consent__choice p,
.fg-cookie-consent__choice span > span {
  margin: 0.25rem 0 0;
  color: var(--color-steel);
  font-size: var(--fg-text-sm);
  line-height: 1.42;
}

.fg-cookie-consent__always {
  flex: 0 0 auto;
  padding: 0.35rem 0.55rem;
  border-radius: 999px;
  border: 1px solid rgba(46, 172, 102, 0.18);
  background: #eaf5ef;
  color: var(--color-accent-dark);
  font-size: 0.76rem;
  font-weight: 850;
  white-space: nowrap;
}

.fg-cookie-consent__switch {
  position: relative;
  flex: 0 0 auto;
  width: 52px;
  height: 30px;
}

.fg-cookie-consent__switch input[role="switch"] {
  position: absolute;
  z-index: 2;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  appearance: none;
  border: 0 !important;
  background: transparent !important;
  cursor: pointer;
  opacity: 0;
}

.fg-cookie-consent__switch-track {
  position: absolute;
  inset: 0;
  display: block;
  border: 2px solid #6c7b80;
  border-radius: 999px;
  background: #ffffff;
  pointer-events: none;
  transition: background-color 160ms ease, border-color 160ms ease;
}

.fg-cookie-consent__switch-track::before {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #6c7b80;
  content: "";
  transition: transform 160ms ease, background-color 160ms ease;
}

.fg-cookie-consent__switch input[role="switch"]:checked + .fg-cookie-consent__switch-track {
  border-color: var(--color-accent);
  background: var(--color-accent);
}

.fg-cookie-consent__switch input[role="switch"]:checked + .fg-cookie-consent__switch-track::before {
  background: #ffffff;
  transform: translateX(22px);
}

.fg-cookie-consent__switch input[role="switch"]:focus-visible + .fg-cookie-consent__switch-track {
  outline: 3px solid rgba(231, 114, 38, 0.45);
  outline-offset: 3px;
}

@media (max-width: 860px) {
  .fg-cookie-consent__actions--two,
  .fg-cookie-consent__actions--three {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  .fg-cookie-consent {
    width: min(calc(100% - 1rem), 760px);
    max-height: calc(100dvh - 1rem);
    border-radius: 16px;
  }

  .fg-cookie-consent__panel {
    padding: 1.35rem 1.15rem 1.2rem;
    border-radius: 16px;
  }

  .fg-cookie-consent h2 {
    font-size: clamp(1.55rem, 8vw, 1.9rem);
  }

  .fg-cookie-consent h2 + p {
    font-size: var(--fg-text-md);
    line-height: 1.48;
  }

  .fg-cookie-consent__note {
    padding: 0.65rem 0.72rem;
    font-size: 0.82rem;
  }

  .fg-cookie-consent__close:not([hidden]) ~ div h2 {
    padding-right: 2.6rem;
  }

  .fg-cookie-consent__choice {
    min-height: 72px;
    padding: 0.8rem;
  }
}

/* Legend AI assistant preview. Kept separate from consent controls and enquiry forms. */
.legend-assistant {
  position: fixed;
  right: 0;
  bottom: 0;
  z-index: 1100;
  display: grid;
  justify-items: end;
  font-family: var(--font-body);
  /* The wrapper is a transparent positioning box that can cover page content,
     the cookie banner area and CTAs beneath it. It must never intercept taps;
     only the visible launcher, prompt and open chat panel take pointer input. */
  pointer-events: none;
  transition: opacity 160ms ease, visibility 160ms ease;
}

.legend-assistant.is-cookie-modal-open {
  visibility: hidden;
  opacity: 0;
}

.legend-assistant__launcher-wrap {
  display: flex;
  gap: 0.8rem;
  align-items: center;
  min-width: 0;
  min-height: 126px;
  margin: 0 1rem calc(1rem + var(--legend-cookie-offset, 0px)) 0;
  pointer-events: none;
  transition: opacity 140ms ease, transform 180ms ease, visibility 140ms ease;
}

.legend-assistant__launcher {
  position: relative;
  z-index: 1;
  display: block;
  flex: 0 0 auto;
  width: 118px;
  min-width: 0;
  min-height: 126px;
  padding: 0;
  overflow: visible;
  border: 0;
  background: transparent;
  color: var(--color-steel);
  cursor: pointer;
  pointer-events: auto;
  font: inherit;
  text-align: center;
  transition: opacity 140ms ease, transform 180ms ease, visibility 140ms ease;
}

.legend-assistant__launcher:hover {
  transform: translateY(-3px);
}

.legend-assistant__launcher:focus-visible,
.legend-assistant__close:focus-visible,
.legend-assistant__prompt-action:focus-visible,
.legend-assistant__prompt-close:focus-visible,
.legend-assistant__consent button:focus-visible,
.legend-assistant__consent a:focus-visible,
.legend-assistant__notice button:focus-visible,
.legend-assistant__composer textarea:focus-visible,
.legend-assistant__composer button:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
}

.legend-assistant__prompt {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.35rem;
  align-items: start;
  max-width: 190px;
  padding: 0.34rem 0.38rem 0.34rem 0.72rem;
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-radius: 12px 12px 4px 12px;
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 12px 32px rgba(0, 45, 58, 0.2);
  line-height: 1.18;
  pointer-events: auto;
  transform-origin: right bottom;
  visibility: hidden;
  opacity: 0;
  transform: translateX(10px) scale(0.92);
  transition: opacity 240ms ease, transform 360ms cubic-bezier(0.22, 1, 0.36, 1), visibility 240ms ease;
}

.legend-assistant.is-prompt-visible:not(.is-prompt-dismissed):not(.is-open):not(.is-transitioning) .legend-assistant__prompt {
  visibility: visible;
  opacity: 1;
  transform: translateX(0) scale(1);
}

.legend-assistant__prompt::after {
  position: absolute;
  right: -9px;
  bottom: 12px;
  width: 17px;
  height: 17px;
  border-top: 1px solid rgba(0, 45, 58, 0.12);
  border-right: 1px solid rgba(0, 45, 58, 0.12);
  background: #ffffff;
  content: '';
  transform: rotate(45deg);
}

.legend-assistant__prompt-action {
  display: grid;
  gap: 0.2rem;
  min-width: 0;
  padding: 0.34rem 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  font: inherit;
  line-height: inherit;
  text-align: left;
}

.legend-assistant__prompt-action strong {
  font-size: 0.98rem;
  font-weight: 850;
}

.legend-assistant__prompt-action small {
  color: var(--color-muted);
  font-size: 0.7rem;
  font-weight: 700;
}

.legend-assistant__prompt-close {
  display: grid;
  width: 1.8rem;
  height: 1.8rem;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 50%;
  background: rgba(0, 45, 58, 0.08);
  color: var(--color-steel);
  cursor: pointer;
  transition: background 160ms ease, color 160ms ease, transform 160ms ease;
}

.legend-assistant__prompt-close svg {
  width: 14px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-width: 1.8;
}

.legend-assistant__prompt-close:hover,
.legend-assistant__prompt-close:focus-visible {
  background: var(--color-steel);
  color: #ffffff;
  transform: scale(1.04);
}

.legend-assistant.is-prompt-dismissed .legend-assistant__prompt,
.legend-assistant.is-prompt-dismissed .legend-assistant__prompt-close {
  visibility: hidden;
  pointer-events: none;
  opacity: 0;
}

.legend-assistant__character {
  position: relative;
  display: block;
  flex: 0 0 auto;
  width: 118px;
  aspect-ratio: 192 / 208;
  overflow: visible;
  filter: drop-shadow(0 12px 12px rgba(0, 45, 58, 0.24));
}

.legend-assistant__character::before {
  position: absolute;
  inset: 14% 10% 10%;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  content: '';
  filter: blur(19px);
  transform: scale(0.9);
}

.legend-assistant__character .legend-sprite {
  z-index: 1;
}

.legend-assistant.is-open .legend-assistant__launcher-wrap,
.legend-assistant.is-transitioning .legend-assistant__launcher-wrap {
  visibility: hidden;
  pointer-events: none;
  opacity: 0;
}

.legend-assistant.is-quote-frame-loaded .legend-assistant__launcher-wrap {
  visibility: hidden;
  pointer-events: none;
  opacity: 0;
  transform: translateY(8px);
}

.legend-assistant.is-open .legend-assistant__prompt {
  visibility: hidden;
  opacity: 0;
  transform: translateX(8px) scale(0.96);
}

.legend-sprite {
  --legend-column: 0;
  --legend-row: 0;
  position: absolute;
  inset: 0;
  display: block;
  overflow: hidden;
}

.legend-sprite img {
  position: absolute;
  top: 0;
  left: 0;
  width: 800%;
  max-width: none;
  height: 1100%;
  transform: translate(calc(var(--legend-column) * -12.5%), calc(var(--legend-row) * -9.090909%));
}

.legend-sleep-sprite {
  --legend-sleep-column: 0;
  position: absolute;
  inset: 0;
  z-index: 2;
  display: block;
  overflow: hidden;
  visibility: hidden;
  opacity: 0;
}

.legend-sleep-sprite img {
  position: absolute;
  top: 0;
  left: 0;
  width: 800%;
  max-width: none;
  height: 100%;
  transform: translateX(calc(var(--legend-sleep-column) * -12.5%));
}

.legend-assistant.is-sleeping .legend-assistant__character .legend-sprite,
.legend-assistant.is-sleeping .legend-assistant__roamer .legend-sprite {
  visibility: hidden;
  opacity: 0;
}

.legend-assistant.is-sleeping .legend-assistant__character .legend-sleep-sprite,
.legend-assistant.is-sleeping .legend-assistant__roamer .legend-sleep-sprite {
  visibility: visible;
  opacity: 1;
}

.legend-assistant__panel {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  pointer-events: auto;
  width: min(420px, 100vw);
  height: 100vh;
  height: 100dvh;
  min-height: 0;
  box-sizing: border-box;
  margin: 0;
  overflow: hidden;
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-width: 0 0 0 1px;
  border-radius: 8px 0 0 8px;
  background: #f6f9f8;
  box-shadow: 0 24px 72px rgba(0, 45, 58, 0.3);
  transform-origin: right center;
  animation: legend-panel-in 320ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.legend-assistant__panel.is-closing {
  animation: legend-panel-out 280ms ease-in both;
}

.legend-assistant__panel.is-restored {
  animation: none;
}

.legend-assistant__panel[hidden] {
  display: none;
}

.legend-assistant__header {
  position: relative;
  flex: 0 0 150px;
  min-height: 150px;
  padding: 0.9rem 3.4rem 0.8rem 0.9rem;
  overflow: hidden;
  background:
    radial-gradient(circle at 76% 112%, rgba(93, 218, 153, 0.26) 0, rgba(46, 172, 102, 0.1) 28%, transparent 54%),
    linear-gradient(128deg, #002d3a 0%, #043a47 58%, #07515a 100%);
  color: #ffffff;
  isolation: isolate;
}

.legend-assistant__header::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 2;
  height: 2px;
  background: linear-gradient(90deg, transparent 0 42%, rgba(100, 217, 154, 0.72) 72%, transparent 100%);
  content: '';
  pointer-events: none;
}

.legend-assistant__identity {
  position: relative;
  z-index: 2;
  min-width: 0;
  width: 172px;
}

.legend-assistant__identity p,
.legend-assistant__identity h2 {
  margin: 0;
  color: inherit;
}

.legend-assistant__eyebrow {
  color: rgba(255, 255, 255, 0.7) !important;
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.legend-assistant__identity h2 {
  font-size: 1.08rem;
  line-height: 1.15;
}

.legend-assistant__status {
  display: flex;
  gap: 0.35rem;
  align-items: center;
  margin-top: 0.2rem !important;
  color: rgba(255, 255, 255, 0.78) !important;
  font-size: var(--fg-text-2xs);
}

.legend-assistant__status span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #64d99a;
  box-shadow: 0 0 0 3px rgba(100, 217, 154, 0.16);
}

.legend-assistant__about {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  margin-top: 0.55rem;
  padding: 0.25rem 0.55rem;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: var(--fg-tag-radius-sm);
  color: #ffffff;
  font-size: 0.7rem;
  font-weight: var(--fg-tag-weight);
  line-height: 1;
  text-decoration: none;
}

.legend-assistant__about:hover,
.legend-assistant__about:focus-visible {
  border-color: var(--color-accent);
  background: rgba(255, 255, 255, 0.1);
}

.legend-assistant__about:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.legend-assistant__stage {
  --legend-roam-distance: 86px;
  position: absolute;
  z-index: 1;
  right: 2.65rem;
  bottom: 0;
  width: 224px;
  height: 150px;
  overflow: hidden;
}

.legend-assistant__stage::before {
  position: absolute;
  right: 4px;
  bottom: -34px;
  left: 4px;
  height: 116px;
  border-radius: 50%;
  background: radial-gradient(ellipse at center, rgba(229, 250, 239, 0.34) 0, rgba(100, 217, 154, 0.16) 44%, transparent 72%);
  content: '';
  pointer-events: none;
}

.legend-assistant__stage::after {
  position: absolute;
  right: 8px;
  bottom: 7px;
  left: 8px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(224, 248, 236, 0.48) 18% 82%, transparent);
  content: '';
  pointer-events: none;
}

.legend-assistant__roamer {
  position: absolute;
  bottom: -4px;
  left: 12px;
  width: 104px;
  aspect-ratio: 192 / 208;
  visibility: hidden;
  opacity: 0;
  transition: transform 2200ms linear;
}

.legend-assistant.has-arrived .legend-assistant__roamer {
  visibility: visible;
  opacity: 1;
}

.legend-assistant__roamer.is-at-right {
  transform: translateX(var(--legend-roam-distance));
}

.legend-assistant__traveller {
  position: fixed;
  z-index: 10000;
  display: block;
  overflow: hidden;
  pointer-events: none;
  filter: drop-shadow(0 12px 12px rgba(0, 45, 58, 0.24));
  transform-origin: top left;
  will-change: transform;
}

.legend-assistant__close {
  position: absolute;
  z-index: 3;
  top: 0.75rem;
  right: 0.75rem;
  display: grid;
  width: 38px;
  height: 38px;
  padding: 0;
  place-items: center;
  border: 0;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.1);
