}

.fg-aw-story__canvas,
.fg-aw-story__fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.fg-aw-story__shade {
  z-index: 1;
  background:
    linear-gradient(90deg, rgba(0, 29, 38, 0.82) 0%, rgba(0, 45, 58, 0.5) 42%, rgba(0, 45, 58, 0.08) 76%),
    linear-gradient(0deg, rgba(0, 29, 38, 0.56), transparent 48%, rgba(0, 29, 38, 0.14));
}

.fg-aw-story__grain {
  z-index: 2;
  opacity: 0.16;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}

.fg-aw-story__content {
  position: relative;
  z-index: 3;
  height: 100%;
}

.fg-aw-story__panel {
  position: absolute;
  left: 0;
  top: 50%;
  width: min(690px, calc(100% - 2rem));
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translate3d(0, calc(-50% + 42px), 0);
  transition: opacity 360ms ease, transform 520ms cubic-bezier(0.2, 0.75, 0.25, 1);
}

.fg-aw-story__panel.is-active {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translate3d(0, -50%, 0);
}

.fg-aw-story__panel h1,
.fg-aw-story__panel h2 {
  max-width: 680px;
  margin: 0.5rem 0 1rem;
  color: #ffffff;
  font-size: clamp(2.65rem, 6vw, var(--fg-font-size-max));
  line-height: 0.96;
  letter-spacing: -0.035em;
  text-wrap: balance;
}

.fg-aw-story__panel h2 {
  font-size: clamp(2.35rem, 5vw, var(--fg-font-size-max));
}

.fg-aw-story__panel > p:not(.eyebrow) {
  max-width: 590px;
  margin: 0 0 1.5rem;
  color: rgba(255, 255, 255, 0.84);
  font-size: clamp(1.05rem, 1.8vw, 1.32rem);
}

.fg-aw-story__number {
