}

.fg-aw-story__progress {
  position: absolute;
  z-index: 4;
  left: max(1rem, calc((100vw - var(--container)) / 2));
  right: max(1rem, calc((100vw - var(--container)) / 2));
  bottom: 2rem;
  height: 2px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.24);
}

.fg-aw-story__progress span {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--color-accent);
  transform: scaleX(0);
  transform-origin: left center;
  will-change: transform;
}

.fg-aw-story__scroll-cue {
  position: absolute;
  z-index: 4;
  right: max(1rem, calc((100vw - var(--container)) / 2));
  bottom: 2.55rem;
  margin: 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: var(--fg-text-2xs);
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

@media (prefers-reduced-motion: reduce) {
  .fg-aw-story {
    height: auto;
    min-height: 0;
  }

  .fg-aw-story__stage {
    position: relative;
    height: auto;
    min-height: 100svh;
  }

  .fg-aw-story__canvas,
  .fg-aw-story__fallback {
    height: 100svh;
  }

  .fg-aw-story__content {
