    padding-top: 20svh;
    padding-bottom: 5rem;
  }

  .fg-aw-story__panel,
  .fg-aw-story__panel.is-active {
    position: relative;
    top: auto;
    bottom: auto;
    width: min(690px, 100%);
    padding: 3rem 0;
    border-top: 1px solid rgba(255, 255, 255, 0.22);
    opacity: 1;
    visibility: visible;
    pointer-events: auto;
    transform: none;
    transition: none;
  }

  .fg-aw-story__panel:first-child {
