.fg-product-intel__badge {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 0.45rem;
  padding: 0.5rem 0.75rem;
  border: 1px solid rgba(11, 61, 74, 0.14);
  border-radius: var(--fg-tag-radius);
  background: transparent;
  color: var(--color-steel);
  font-size: var(--fg-text-xs);
  font-weight: var(--fg-tag-weight);
  line-height: 1.1;
}

.fg-product-intel__badge--system {
  min-width: 172px;
  min-height: 66px;
  justify-content: center;
  padding: 0.45rem 0.9rem;
  border-color: rgba(0, 45, 58, 0.14);
  background: #ffffff;
}

.fg-product-intel__badge--system:not(:has(img)) {
  min-width: 86px;
  justify-content: center;
  background: #ffffff;
  color: var(--color-steel);
  font-size: var(--fg-text-md);
  letter-spacing: -0.02em;
}

.fg-product-intel__badge--technology {
  min-width: 172px;
  min-height: 66px;
  justify-content: center;
  padding: 0.45rem 0.9rem;
  border-color: rgba(0, 45, 58, 0.14);
  background: #ffffff;
}

.fg-product-intel__badge img {
  display: block;
  width: auto;
  max-width: 132px;
  height: 30px;
  object-fit: contain;
}

.fg-product-intel__badge--system img {
  max-width: 160px;
  height: 52px;
}

.fg-product-intel__badge--technology img {
  max-width: 160px;
  height: 52px;
}

.fg-product-intel__media {
  position: relative;
  min-height: 360px;
  overflow: hidden;
  margin: 0;
  background: var(--color-steel);
}

.fg-product-intel__media img {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 360px;
  object-fit: cover;
}

.fg-product-intel__media::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(0, 45, 58, 0.54), transparent 56%);
}

/* The Prestige profile render is white-backed, so this slot goes white when it
   holds the turntable rather than keeping the steel it uses behind photography.
   `contain` because the source is square and the slot is not: on white the
   letterbox is invisible, and cropping would cut into the frame section the
   video exists to show. The bottom scrim stays, since the caption sits on it. */
.fg-product-intel__media--turntable {
  background: #fbfbfb;
}

/* The shared scrim is sized for photography, where it lifts a white caption off
   a busy image. Over a white render it washed the bottom half of the frame grey,
   which is the opposite of what this slot is for. Keep just enough to seat the
   caption. */
.fg-product-intel__media--turntable::after {
  background: linear-gradient(0deg, rgba(0, 45, 58, 0.34), transparent 26%);
}

.fg-product-intel__media--turntable video {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 360px;
  object-fit: contain;
}

.fg-product-intel__media figcaption {
  position: absolute;
  left: 1rem;
  right: 1rem;
  bottom: 1rem;
  z-index: 1;
  display: grid;
  gap: 0.15rem;
  padding: 0.85rem;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 8px;
  background: rgba(0, 45, 58, 0.62);
  color: #ffffff;
  backdrop-filter: blur(14px);
}

.fg-product-intel__media figcaption span {
  color: var(--color-accent);
  font-size: var(--fg-text-2xs);
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.fg-product-intel__media figcaption strong {
  line-height: 1.1;
}

.fg-product-intel__explorer {
  grid-column: 1;
  display: grid;
  grid-template-columns: minmax(230px, 0.34fr) minmax(0, 1fr);
  gap: var(--fg-space-4);
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.88);
  box-shadow: var(--fg-shadow-lg);
  overflow: hidden;
}

.fg-product-intel__nav-hint {
  display: none;
}

.fg-product-intel__nav {
  display: grid;
  align-content: start;
  gap: 0.35rem;
  max-width: 100%;
  padding: 0.6rem;
  border-right: 1px solid var(--color-line);
  background: linear-gradient(180deg, rgba(246, 251, 249, 0.96), #ffffff);
  contain: inline-size;
}

.fg-product-intel__nav button {
  display: grid;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: var(--fg-space-3);
  align-items: center;
  min-height: 66px;
  cursor: pointer;
  padding: 0.72rem 0.85rem;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--color-steel);
  font: inherit;
  text-align: left;
  transition: background 180ms ease, border-color 180ms ease, transform 180ms ease, box-shadow 180ms ease;
}

.fg-product-intel__nav button:hover,
.fg-product-intel__nav button:focus-visible,
.fg-product-intel__nav button.is-active {
  border-color: rgba(46, 172, 102, 0.28);
  background: #ffffff;
  box-shadow: 0 12px 26px rgba(0, 45, 58, 0.08);
}

.fg-product-intel__nav button.is-active {
  transform: translateX(4px);
}

.fg-product-intel__nav button span {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  border-radius: 999px;
  background: rgba(46, 172, 102, 0.12);
  color: var(--color-accent-dark);
  font-size: var(--fg-text-xs);
  font-weight: 800;
}

.fg-product-intel__nav button.is-active span {
  background: var(--color-accent);
  color: #ffffff;
}

.fg-product-intel__nav button strong {
  font-size: 0.95rem;
  line-height: 1.15;
}

.fg-product-intel__stage {
  min-height: 100%;
  padding: clamp(1.15rem, 2vw, 1.8rem);
}

.fg-product-intel__stage article {
  display: grid;
  gap: var(--fg-space-4);
  min-height: 100%;
  align-content: start;
}

.fg-product-intel__stage article[hidden] {
  display: none;
}

.fg-product-intel__stage h3 {
  max-width: 620px;
  color: var(--color-steel);
  font-size: clamp(1.15rem, 1.55vw, 1.5rem);
  line-height: 1.22;
}

.fg-product-intel__stage p:not(.eyebrow) {
  max-width: 62ch;
  margin: 0;
  color: var(--color-muted);
  line-height: 1.55;
}

.fg-product-intel__stage-points {
  display: grid;
  gap: 0.55rem;
  margin-top: 0.1rem;
  padding: 1rem;
  border: 1px solid rgba(46, 172, 102, 0.18);
  border-radius: 8px;
  background: rgba(246, 251, 249, 0.86);
}

.fg-product-intel__stage-points span {
  color: var(--color-accent-dark);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.fg-product-intel__stage-points ul {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-product-intel__stage-points li {
  position: relative;
  padding-left: 1.05rem;
  color: var(--color-muted);
  line-height: 1.5;
}

.fg-product-intel__stage-points li::before {
  position: absolute;
  top: 0.64em;
  left: 0;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 999px;
  background: var(--color-accent);
  content: "";
}

.fg-product-intel__checks {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--fg-space-4);
}

.fg-product-intel__checks article {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr);
  gap: var(--fg-space-3);
  min-height: 100%;
  padding: clamp(1rem, 1.8vw, 1.25rem);
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 32px rgba(0, 45, 58, 0.07);
}

.fg-product-intel__checks article > span {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  border-radius: 999px;
  background: rgba(46, 172, 102, 0.12);
  color: var(--color-accent-dark);
  font-size: 0.76rem;
  font-weight: 850;
}

.fg-product-intel__checks h3 {
  margin: 0.15rem 0 0;
  color: var(--color-steel);
  font-size: clamp(1rem, 1.25vw, 1.22rem);
  line-height: 1.22;
}

.fg-product-intel__checks p:not(.eyebrow) {
  margin: 0.45rem 0 0;
  color: var(--color-muted);
  line-height: 1.5;
}

.fg-product-intel__choices-strip {
  grid-column: 1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 0.9rem 1.15rem;
  align-items: start;
  padding: 0.95rem 1.05rem;
  border: 1px solid rgba(46, 172, 102, 0.18);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 14px 36px rgba(0, 45, 58, 0.06);
}

.fg-product-intel__choices-strip span {
  color: var(--color-accent-dark);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1.2;
  text-transform: uppercase;
}

.fg-product-intel__choices-strip ul {
  display: grid;
  grid-template-columns: repeat(2, minmax(190px, 1fr));
  gap: 0.45rem 1.1rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-product-intel__choices-strip li {
  position: relative;
  padding-left: 1rem;
  color: var(--color-muted);
  font-size: 0.9rem;
  line-height: 1.38;
}

.fg-product-intel__choices-strip li::before {
  position: absolute;
  top: 0.58em;
  left: 0;
  width: 0.38rem;
  height: 0.38rem;
  border-radius: 999px;
  background: var(--color-accent);
  content: "";
}

.fg-product-intel__summary {
  grid-column: 2;
  grid-row: 2 / span 2;
  display: grid;
  align-content: start;
  gap: 0.9rem;
  padding: clamp(1rem, 1.8vw, 1.35rem);
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background:
    linear-gradient(160deg, rgba(0, 45, 58, 0.96), rgba(0, 70, 76, 0.9)),
    var(--color-steel);
  color: #ffffff;
  box-shadow: 0 22px 54px rgba(0, 45, 58, 0.14);
}

.fg-product-intel__summary span {
  color: var(--color-accent);
  font-size: var(--fg-text-xs);
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.fg-product-intel__summary p {
  margin: 0.55rem 0 0;
  color: rgba(255, 255, 255, 0.78);
  max-width: 24ch;
  font-size: 0.98rem;
  line-height: 1.5;
}

.fg-product-intel__summary-image {
  overflow: hidden;
  margin: 0;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.08);
}

.fg-product-intel__summary-image img {
  display: block;
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.fg-product-intel__summary .button {
  justify-self: start;
  width: auto;
  max-width: 22ch;
  margin-top: 0.2rem;
  border-color: #ffffff;
  background: #ffffff;
  color: var(--color-steel);
}

.fg-product-gallery-band {
  background: transparent;
}

.fg-composite-glass {
  padding: clamp(3rem, 6vw, 5rem) 0;
  background:
    radial-gradient(circle at 8% 12%, rgba(46, 172, 102, 0.16), transparent 30%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(246, 251, 249, 0.8));
}

.fg-composite-glass__head {
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(300px, 0.46fr);
  gap: clamp(1rem, 3vw, 2rem);
  align-items: end;
  margin-bottom: clamp(1.2rem, 2.5vw, 2rem);
}

.fg-composite-glass__head h2 {
  max-width: 720px;
  color: var(--color-steel);
  font-size: clamp(1.75rem, 2.7vw, 2.65rem);
  line-height: 1.04;
}

.fg-composite-glass__head p:not(.eyebrow) {
  margin: 0;
  color: var(--color-muted);
  line-height: 1.58;
}

/* SIZED TO THE ARTWORK, NOT TO THE PAGE. Nine of the eleven glass images are
   250x250 and the other two 458x464. The previous grid ran six columns with
   every card spanning two and the first two spanning three, which at 1440
   stretched a 250px source across ~570px — a 2.3x upscale on a photograph of a
   fine glass pattern, which is exactly the detail that goes to mush. Cards now
   sit near their native size and the set reads as a swatch board rather than
   two hero tiles and a tail. */
.fg-composite-glass__grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 0.7rem;
  padding: clamp(0.75rem, 1.6vw, 1rem);
  border: 1px solid rgba(0, 45, 58, 0.1);
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(255, 255, 255, 0.82), rgba(246, 251, 249, 0.62)),
    rgba(255, 255, 255, 0.7);
  box-shadow: var(--fg-shadow-lg);
  backdrop-filter: blur(12px);
}

.fg-composite-glass-card {
  position: relative;
  display: grid;
  grid-template-rows: minmax(150px, 1fr) auto;
  min-height: 250px;
  overflow: hidden;
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.88), #ffffff),
    #ffffff;
  box-shadow: 0 14px 34px rgba(0, 45, 58, 0.07);
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

/* The first-two "featured" treatment is gone deliberately. It span-3'd the two
   biggest cards, which is where the worst upscaling was, and it implied Lunna
   and Aspen are the headline designs when the order in `site-data.php` is not a
   ranking. Eleven equal swatches is the honest presentation. */

.fg-composite-glass-card:hover,
.fg-composite-glass-card:focus-within {
  border-color: rgba(46, 172, 102, 0.38);
  box-shadow: var(--fg-shadow-xl);
  transform: translateY(-3px);
}

.fg-composite-glass-card__number {
  position: absolute;
  top: 0.85rem;
  left: 0.85rem;
  z-index: 2;
  display: inline-flex;
  min-width: 2.35rem;
  min-height: 2.35rem;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: 999px;
  background: rgba(0, 45, 58, 0.72);
  color: #ffffff;
  font-size: var(--fg-text-2xs);
  font-weight: 850;
  letter-spacing: 0.08em;
  backdrop-filter: blur(8px);
}

.fg-composite-glass-card figure {
  position: relative;
  margin: 0;
  min-height: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.88), transparent 44%),
    linear-gradient(135deg, rgba(0, 45, 58, 0.08), rgba(46, 172, 102, 0.1)),
    #f7fbf9;
}

.fg-composite-glass-card figure::after {
  content: "";
  position: absolute;
  inset: auto 0 0;
  height: 42%;
  background: linear-gradient(180deg, rgba(0, 45, 58, 0), rgba(0, 45, 58, 0.16));
  pointer-events: none;
}

.fg-composite-glass-card img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 220ms ease;
}

.fg-composite-glass-card:hover img,
.fg-composite-glass-card:focus-within img {
  transform: scale(1.035);
}

.fg-composite-glass-card div {
  display: grid;
  align-content: start;
  gap: 0.4rem;
  min-height: 126px;
  padding: 0.95rem;
}

.fg-composite-glass-card h3 {
  color: var(--color-steel);
  font-size: clamp(1.08rem, 1.4vw, 1.32rem);
  line-height: 1.08;
}

.fg-composite-glass-card p {
  margin: 0;
  color: var(--color-muted);
  font-size: 0.9rem;
  line-height: 1.45;
}

.fg-composite-glass__note {
  max-width: 920px;
  margin: 0.85rem 0 0;
  padding: 0.85rem 1rem;
  border: 1px solid rgba(46, 172, 102, 0.18);
  border-radius: 8px;
  background: rgba(246, 251, 249, 0.86);
  color: var(--color-muted);
  font-size: 0.94rem;
}

.fg-product-visuals {
  background: transparent;
}

.fg-product-visuals__grid {
  display: grid;
  grid-template-columns: minmax(0, 0.58fr) minmax(300px, 0.42fr);
  gap: var(--fg-space-4);
  align-items: start;
}

.fg-product-visuals__mosaic {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.65rem;
  padding: 0.65rem;
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.78);
  box-shadow: var(--fg-shadow-md);
}

.fg-product-visuals__mosaic figure {
  position: relative;
  overflow: hidden;
  margin: 0;
  aspect-ratio: 4 / 3;
  border-radius: 6px;
  background: var(--color-steel);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.fg-product-visuals__mosaic figure:nth-child(1) {
  background: #ffffff;
}

.fg-product-visuals__mosaic a {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  color: inherit;
}

.fg-product-visuals__mosaic a::after {
  content: "Preview image";
  position: absolute;
  right: 0.75rem;
  bottom: 0.75rem;
  z-index: 1;
  padding: 0.45rem 0.62rem;
  border-radius: 999px;
  background: rgba(0, 45, 58, 0.82);
  color: #ffffff;
  font-size: var(--fg-text-2xs);
  font-weight: 850;
  letter-spacing: 0.04em;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 180ms ease, transform 180ms ease;
}

.fg-product-visuals__mosaic figure:hover,
.fg-product-visuals__mosaic figure:has(a:focus-visible) {
  transform: translateY(-3px);
  box-shadow: 0 18px 42px rgba(0, 45, 58, 0.14);
}

.fg-product-visuals__mosaic a:hover::after,
.fg-product-visuals__mosaic a:focus-visible::after {
  opacity: 1;
  transform: translateY(0);
}

.fg-product-visuals__mosaic img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition: transform 220ms ease, filter 220ms ease;
}

.fg-product-visuals__mosaic a:hover img,
.fg-product-visuals__mosaic a:focus-visible img {
  filter: saturate(1.05) contrast(1.04);
  transform: scale(1.035);
}

html.fg-gallery-lightbox-open,
html.fg-gallery-lightbox-open body {
  overflow: hidden;
}

.fg-gallery-lightbox {
  position: fixed;
  inset: 0;
  z-index: 3000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: clamp(1rem, 3vw, 2rem);
  background: rgba(0, 28, 36, 0.9);
  backdrop-filter: blur(10px);
}

.fg-gallery-lightbox[hidden] {
  display: none;
}

.fg-gallery-lightbox__figure {
  position: relative;
  display: block;
  width: min(100%, 1180px);
  max-height: min(88svh, 820px);
  margin: 0;
}

.fg-gallery-lightbox__figure img {
  display: block;
  width: 100%;
  max-height: min(88svh, 820px);
  object-fit: contain;
  border-radius: 8px;
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.42);
}

.fg-gallery-lightbox__close,
.fg-gallery-lightbox__arrow {
  position: fixed;
  z-index: 1;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(255, 255, 255, 0.94);
  color: var(--color-steel);
  font: inherit;
  font-weight: 850;
  box-shadow: 0 14px 38px rgba(0, 0, 0, 0.22);
}

.fg-gallery-lightbox__close {
  top: clamp(0.9rem, 2vw, 1.35rem);
  right: clamp(0.9rem, 2vw, 1.35rem);
  min-height: 44px;
  padding: 0.68rem 0.95rem;
  border-radius: 999px;
}

.fg-gallery-lightbox__arrow {
  top: 50%;
  display: grid;
  place-items: center;
  width: clamp(44px, 5vw, 58px);
  height: clamp(44px, 5vw, 58px);
  padding: 0;
  border-radius: 999px;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1;
  transform: translateY(-50%);
}

.fg-gallery-lightbox__arrow--prev {
  left: clamp(0.8rem, 2vw, 1.5rem);
}

.fg-gallery-lightbox__arrow--next {
  right: clamp(0.8rem, 2vw, 1.5rem);
}

.fg-gallery-lightbox__close:focus-visible,
.fg-gallery-lightbox__arrow:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
}

.fg-product-visuals__copy {
  display: grid;
  gap: var(--fg-space-4);
  padding: clamp(1.2rem, 2.4vw, 1.8rem);
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: #ffffff;
  box-shadow: var(--fg-shadow-md);
}

.fg-product-visuals__copy h2 {
  font-size: clamp(1.75rem, 2.7vw, 2.75rem);
}

.fg-product-visuals__copy p {
  margin: 0;
  color: var(--color-muted);
}

.fg-product-visuals__copy ul {
  display: grid;
  gap: 0.65rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-product-visuals__copy li {
  position: relative;
  padding-left: 1.05rem;
  color: var(--color-muted);
}

.fg-product-visuals__copy li::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0.72em;
  width: 0.42rem;
  height: 0.42rem;
  border-radius: 999px;
  background: var(--color-accent);
}

.fg-product-gallery {
  display: grid;
  grid-auto-columns: minmax(280px, 34vw);
  grid-auto-flow: column;
  gap: var(--fg-space-4);
  overflow-x: auto;
  margin-top: 2rem;
  padding: 0 0 1rem;
  scroll-snap-type: x mandatory;
}

.fg-product-gallery figure {
  margin: 0;
  overflow: hidden;
  border-radius: 8px;
  background: var(--color-steel);
  box-shadow: var(--shadow-soft);
  scroll-snap-align: start;
}

.fg-product-gallery img {
  display: block;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
}

.fg-product-options {
  display: grid;
  grid-template-columns: minmax(0, 0.45fr) minmax(0, 1fr);
  gap: var(--fg-space-6);
  align-items: center;
  margin-top: 1rem;
  padding: clamp(1.2rem, 2.4vw, 2rem);
}

.fg-product-options__intro {
  display: grid;
  align-content: start;
  gap: 0.65rem;
}

.fg-product-options--upvc {
  grid-template-columns: minmax(280px, 0.36fr) minmax(0, 1fr);
  grid-template-areas:
    "intro colours"
    "notes colours"
    ". cta";
  align-items: start;
