  z-index: 1;
}

.fg-product-option-card h3 {
  max-width: 14ch;
  margin: 0;
  font-size: clamp(1.2rem, 1.65vw, 1.65rem);
  line-height: 1.08;
}

.fg-product-option-card p {
  margin: 0;
  color: var(--color-muted);
