}

.fg-colour-hub-hero__grid {
  display: grid;
  grid-template-columns: minmax(0, 0.82fr) minmax(360px, 0.58fr);
  gap: clamp(1.5rem, 5vw, 4.5rem);
  align-items: center;
}

.fg-colour-hub-hero h1 {
  max-width: 15ch;
