}

.fg-colour-hub-hero p:not(.eyebrow) {
  max-width: 42rem;
  color: var(--color-muted);
  font-size: clamp(1rem, 1.35vw, 1.18rem);
}

.fg-colour-hub-hero__visual {
  position: relative;
  align-self: center;
}

.fg-colour-hub-hero__photo {
  position: relative;
  margin: 0;
  overflow: hidden;
  border: 1px solid rgba(0, 45, 58, 0.11);
  border-radius: 8px;
