}

.fg-colour-next__title {
  display: block;
  margin: 0.35rem 0 0.6rem;
  font-size: clamp(1.5rem, 2.4vw, 2.15rem);
  font-weight: 850;
  line-height: 1.06;
}

.fg-colour-next__text {
  display: block;
  max-width: 46ch;
  margin-bottom: clamp(1rem, 2vw, 1.4rem);
  color: var(--color-muted);
  font-size: clamp(0.95rem, 1.2vw, 1.05rem);
