.fg-colour-hub__material {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(1rem, 2.6vw, 1.8rem);
  align-items: center;
  margin-top: 1rem;
  padding: clamp(1.1rem, 2.4vw, 1.8rem) clamp(1rem, 3vw, 2rem) clamp(1.4rem, 3vw, 2.2rem);
  border: 1px solid rgba(0, 45, 58, 0.11);
