  width: min(100%, 980px);
  margin: 0 auto;
  overflow: visible;
  cursor: grab;
  touch-action: pan-y;
}

.fg-colour-carousel.is-dragging {
  cursor: grabbing;
}

.fg-colour-carousel__viewport {
  position: relative;
  overflow: visible;
  min-height: clamp(520px, 46vw, 620px);
  background:
    radial-gradient(circle at 50% 48%, rgba(46, 172, 102, 0.1), transparent 35%),
    radial-gradient(ellipse at 50% 86%, rgba(0, 45, 58, 0.08), transparent 42%);
  perspective: 1100px;
}

.fg-colour-carousel__track {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
}

.fg-colour-carousel__slide {
  --offset: 0;
  --abs-offset: 0;
  --scale: 1;
  --z: 1;
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  grid-template-rows: minmax(0, 1fr) auto;
  width: min(58%, 430px);
  margin: 0;
  overflow: hidden;
  border: 1px solid rgba(0, 45, 58, 0.11);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 18px 42px rgba(0, 45, 58, 0.13);
  opacity: 0.44;
  pointer-events: none;
  transform:
    translate(-50%, -50%)
    translateX(calc(var(--offset) * clamp(118px, 18vw, 215px)))
    translateZ(calc((1 - var(--abs-offset)) * 72px))
    rotateY(calc(var(--offset) * -24deg))
    scale(var(--scale));
  transform-origin: center;
  transition:
    transform 430ms cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 260ms ease,
    filter 260ms ease,
    box-shadow 260ms ease;
  z-index: var(--z);
}

.fg-colour-carousel.is-dragging .fg-colour-carousel__slide {
  transition:
    opacity 180ms ease,
    filter 180ms ease,
    box-shadow 180ms ease;
}

.fg-colour-carousel__slide.is-active {
  opacity: 1;
  pointer-events: auto;
  box-shadow: 0 24px 58px rgba(0, 45, 58, 0.18);
}

.fg-colour-carousel__slide.is-near {
  opacity: 0.68;
  cursor: pointer;
  pointer-events: auto;
}

.fg-colour-carousel__slide.is-hidden {
  opacity: 0;
  pointer-events: none;
}

.fg-colour-carousel__slide img,
.fg-colour-carousel__slide i {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 1;
  background: linear-gradient(180deg, #ffffff, color-mix(in srgb, var(--swatch) 11%, #ffffff));
  object-fit: cover;
  -webkit-user-drag: none;
  user-select: none;
}

.fg-colour-carousel__slide > div {
  display: grid;
  gap: 0.28rem;
  min-height: 104px;
  padding: 0.9rem 1rem 1rem;
  border-top: 1px solid rgba(0, 45, 58, 0.08);
  background: #ffffff;
}

.fg-colour-carousel__slide span {
  color: var(--color-accent-dark);
  font-size: 0.76rem;
  font-weight: 900;
}

.fg-colour-carousel__slide h3 {
  margin: 0;
  color: var(--color-steel);
  font-size: clamp(1.1rem, 1.5vw, 1.45rem);
  line-height: 1.1;
}

.fg-colour-carousel__slide p {
  margin: 0;
  color: var(--color-muted);
  font-weight: 750;
  line-height: 1.35;
}

.fg-colour-carousel__controls {
