  height: 44px;
  border: 1px solid rgba(0, 45, 58, 0.14);
  border-radius: 999px;
  background: #ffffff;
  color: var(--color-steel);
  font: inherit;
  font-size: 1.7rem;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 10px 24px rgba(0, 45, 58, 0.08);
}

.fg-colour-carousel__controls span {
