  }
}

.fg-colour-hub__notes {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
}

.fg-colour-hub__notes p {
  margin: 0;
  padding: 0.75rem;
  border: 1px solid rgba(0, 45, 58, 0.09);
