      translateX(calc(var(--offset) * 132px))
      translateZ(calc((1 - var(--abs-offset)) * 48px))
      rotateY(calc(var(--offset) * -20deg))
      scale(var(--scale));
  }

  .fg-colour-carousel__slide img,
  .fg-colour-carousel__slide i {
