.fg-obscure-stage__viewport {
  --mx: 0;
  --my: 0;
  position: relative;
  min-height: clamp(380px, 44vw, 560px);
  overflow: hidden;
  border-radius: 8px;
  background: #dfe9e8;
  perspective: 1200px;
  transform-style: preserve-3d;
  isolation: isolate;
  touch-action: pan-y;
}

.fg-obscure-stage__photo,
.fg-obscure-stage__glass,
.fg-obscure-stage__shine,
.fg-obscure-stage__scan {
  position: absolute;
  inset: 0;
}

.fg-obscure-stage__photo {
  width: 116%;
  height: 116%;
  max-width: none;
  object-fit: cover;
  object-position: 52% 44%;
  filter: contrast(1.08) saturate(1.05);
  transform: translate3d(calc(var(--mx) * -12px - 8%), calc(var(--my) * -10px - 8%), -80px) scale(1.08);
}

.fg-obscure-stage__glass {
  z-index: 2;
  background-image: linear-gradient(115deg, rgba(255, 255, 255, 0.48), rgba(255, 255, 255, 0.04) 42%, rgba(0, 45, 58, 0.14)), var(--active-texture);
  background-size: 116% 116%, 112% 112%;
  background-position: calc(50% + var(--mx) * 22px) calc(50% + var(--my) * 14px), calc(50% + var(--mx) * 54px) calc(50% + var(--my) * 38px);
  mix-blend-mode: screen;
  opacity: calc(0.42 + min(var(--privacy), 5) * 0.07);
  transform: translate3d(calc(var(--mx) * 22px), calc(var(--my) * 16px), 90px) rotateY(calc(var(--mx) * -9deg)) rotateX(calc(var(--my) * 7deg)) scale(1.045);
  transform-origin: center;
  transition: background-image 180ms ease, opacity 180ms ease;
}

.fg-obscure-stage__glass::after {
  content: "";
  position: absolute;
  inset: -8%;
  background: radial-gradient(circle at calc(50% + var(--mx) * 34%) calc(40% + var(--my) * 24%), rgba(255, 255, 255, 0.48), transparent 26%), repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.18) 0 1px, transparent 1px 8px);
  opacity: calc(0.16 + min(var(--privacy), 5) * 0.035);
}

.fg-obscure-stage__shine {
  z-index: 3;
  background: linear-gradient(105deg, transparent 0 22%, rgba(255, 255, 255, 0.64) 34%, transparent 48% 100%);
  opacity: 0.52;
  transform: translateX(calc(var(--mx) * 72px - 18%)) skewX(-12deg);
  pointer-events: none;
}

.fg-obscure-stage__scan {
