.fg-case-page--commercial .fg-case-hero__media,
.fg-case-page--commercial .fg-case-single-hero > img,
.fg-case-page--commercial .fg-case-hero__shade,
.fg-case-page--commercial .fg-case-single-hero__shade {
  display: none;
}

.fg-case-page--commercial .fg-case-hero h1,
.fg-case-page--commercial .fg-case-single-hero h1 {
  color: var(--color-steel);
}

.fg-case-page--commercial .fg-case-hero p:not(.eyebrow),
.fg-case-page--commercial .fg-case-single-hero p:not(.eyebrow) {
  color: var(--color-muted);
}

.fg-case-page--commercial .fg-case-hero__stats span,
.fg-case-page--commercial .fg-case-facts span {
  border-color: rgba(0, 45, 58, 0.12);
  background: rgba(255, 255, 255, 0.8);
  box-shadow: 0 14px 34px rgba(0, 45, 58, 0.08);
}

.fg-case-page--commercial .fg-case-hero__stats strong,
.fg-case-page--commercial .fg-case-facts strong {
  color: var(--color-steel);
}

.fg-case-page--commercial .fg-case-facts small,
.fg-case-page--commercial .fg-case-hero__stats span {
  color: var(--color-muted);
}

.fg-case-page--commercial .fg-case-back {
  color: var(--color-steel);
}

.fg-case-page--commercial .fg-case-single-hero h1 {
  max-width: 760px;
  font-size: clamp(2.15rem, 3.45vw, 3.55rem);
  text-transform: uppercase;
}

.fg-case-page--commercial .fg-case-single-hero p:not(.eyebrow) {
  max-width: 620px;
}

.fg-case-page--commercial .fg-case-snapshot__intro h2,
.fg-case-page--commercial .fg-case-story-block h2 {
  font-size: clamp(1.75rem, 3vw, 3rem);
}

.fg-case-page--commercial .fg-case-story-block::after {
  display: none;
}

.fg-case-page--commercial .fg-case-story-block {
  border-top: 6px solid var(--color-steel);
}

.fg-case-page--commercial .fg-case-story-block > span {
  border-radius: 6px;
  background: var(--color-steel);
}

.fg-case-page--commercial .fg-case-story {
  padding: 2.5rem 0 5rem;
}

.fg-case-page--commercial .fg-case-featured,
.fg-case-page--commercial .fg-case-index,
.fg-case-page--commercial .fg-commercial-record,
.fg-case-page--commercial .fg-case-story,
.fg-case-page--commercial .fg-case-gallery,
.fg-case-page--commercial .fg-case-related,
.fg-case-page--commercial .fg-case-cta {
  background: transparent;
}

.fg-case-page--commercial .fg-case-cta {
  color: var(--color-ink);
}

.fg-case-page--commercial .fg-case-cta__inner {
  padding: clamp(1.2rem, 3vw, 2.4rem);
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 18px 44px rgba(0, 45, 58, 0.08);
  backdrop-filter: blur(12px);
}

.fg-case-page--commercial .fg-case-cta h2 {
  color: var(--color-steel);
}

.fg-case-page--commercial .fg-case-cta p:not(.eyebrow) {
  color: var(--color-muted);
}

.fg-commercial-record {
  padding: 4rem 0 1.5rem;
}

.fg-commercial-record__grid {
  display: grid;
  grid-template-columns: minmax(0, 1.06fr) minmax(340px, 0.64fr);
  gap: var(--fg-space-4);
  align-items: stretch;
}

.fg-commercial-record__media {
  display: grid;
  grid-template-columns: 1fr 0.46fr;
  grid-template-rows: repeat(2, minmax(0, 1fr));
