.fg-commercial-record__media img {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 0;
  object-fit: cover;
}

.fg-commercial-record__facts {
  display: grid;
  gap: var(--fg-space-3);
}

.fg-commercial-record__intro,
.fg-commercial-record__list,
.fg-commercial-record__installed {
  margin: 0;
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-radius: 8px;
