  margin: 0;
  padding: 0;
  list-style: none;
  counter-reset: fg-about-way;
}

.fg-about-pricing__way li {
  position: relative;
  padding-left: 2.1rem;
  counter-increment: fg-about-way;
  color: #ffffff;
  font-size: var(--fg-text-md);
  line-height: 1.45;
}

.fg-about-pricing__way li::before {
  content: counter(fg-about-way);
  position: absolute;
  top: 0;
  left: 0;
