}


/* Work: deliberate mosaic, fixed cells, aligned edges. Five cells close the
   rectangle: the 2x2 lead plus four singles in a four-column grid. */
.fg-about-work__head {
  margin-bottom: clamp(1.15rem, 2.2vw, 1.6rem);
}

.fg-about-work__head p:last-child {
  margin-bottom: 0;
}

.fg-about-work__mosaic {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  grid-auto-rows: clamp(9rem, 13vw, 12.5rem);
  gap: clamp(0.6rem, 1.2vw, 0.9rem);
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-about-cell {
  position: relative;
  overflow: hidden;
  border-radius: 10px;
  background: var(--color-steel);
}

.fg-about-cell--lead {
  grid-column: span 2;
  grid-row: span 2;
}

.fg-about-cell > a {
  display: block;
  width: 100%;
  height: 100%;
  color: inherit;
  text-decoration: none;
}

.fg-about-cell img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.45s ease;
}

.fg-about-cell:hover img,
.fg-about-cell:focus-within img {
  transform: scale(1.05);
}

.fg-about-cell__caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 2rem 0.85rem 0.7rem;
  background: linear-gradient(transparent, rgba(0, 24, 31, 0.88));
  color: #ffffff;
  line-height: 1.3;
}

.fg-about-cell__caption strong {
  display: block;
  font-size: var(--fg-text-md);
  font-weight: 800;
  line-height: 1.2;
}

.fg-about-cell__caption em {
  display: block;
  margin-top: 0.1rem;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.8rem;
  font-style: normal;
}

.fg-about-cell--lead .fg-about-cell__caption {
  padding: 2.5rem 1.1rem 0.95rem;
}

.fg-about-cell--lead .fg-about-cell__caption strong {
  font-size: 1.1rem;
}

.fg-about-work__cta {
  margin-top: clamp(1rem, 2vw, 1.5rem);
}

/* Founders: copy-led, portraits are a supporting pair on the right. */
.fg-about-founders__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 34rem);
  gap: clamp(1.5rem, 3vw, 2.75rem);
  align-items: center;
}

.fg-about-founders__copy p:last-child {
  margin-bottom: 0;
}

.fg-about-founders__people {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.85rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-about-founder {
  overflow: visible;
  border-radius: 0;
}

/* height:auto is required, not optional. These images carry real width/height
   attributes, and the height attribute is a presentational hint that wins over
   aspect-ratio unless one dimension is auto. Without it the portraits render at
   their full 2560px natural height. */
.fg-about-founder img {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 4 / 5;
  border-radius: 10px;
  background: var(--color-steel);
  object-fit: cover;
  object-position: center 16%;
  filter: grayscale(1) contrast(1.04);
}

/* Extra specificity: the shared `.fg-about figure > figcaption` chip rule must
   not turn founder names into overlay chips across their faces. */
.fg-about .fg-about-founder > figcaption {
  position: static;
  bottom: auto;
  left: auto;
  padding: 0.65rem 0.1rem 0;
  border-radius: 0;
  background: none;
  color: var(--color-ink);
  font-size: inherit;
  font-weight: 400;
  text-transform: none;
  letter-spacing: 0;
}

.fg-about-founder figcaption strong {
  display: block;
  font-size: 0.95rem;
  font-weight: 800;
  line-height: 1.2;
}

.fg-about-founder figcaption span {
  display: block;
  color: var(--color-accent-dark);
  font-size: var(--fg-text-xs);
  font-weight: 700;
}

/* Award: the winning job on video, media left. */
.fg-about-award__grid {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: clamp(1.5rem, 3vw, 2.75rem);
  align-items: center;
}

.fg-about-award__media {
  width: 100%;
  aspect-ratio: 1 / 1;
  max-width: 30rem;
  background: var(--color-steel);
}

.fg-about-award__copy p:last-child {
  margin-bottom: 0;
}

.fg-about-award__mark {
  display: flex;
  gap: 0.6rem;
  align-items: center;
  max-width: none;
  margin: 0.9rem 0;
  padding: 0.5rem 0.75rem;
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.88);
  width: fit-content;
  font-size: 0.84rem;
  font-weight: 700;
}

.fg-about-award__mark img {
  width: auto;
  height: 20px;
  object-fit: contain;
}

/* Trust badges */
.fg-about-trust__head {
  margin-bottom: clamp(1.25rem, 2.4vw, 1.85rem);
}

.fg-about-trust__head p:last-child {
  margin-bottom: 0;
}

.fg-about-trust__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.8rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-about-badge {
  display: block;
  height: 100%;
  padding: 1.1rem 1.15rem 1.25rem;
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: #ffffff;
  color: inherit;
  text-decoration: none;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.fg-about-badge:hover,
.fg-about-badge:focus-visible {
  border-color: var(--color-accent);
  transform: translateY(-3px);
  box-shadow: 0 18px 40px rgba(0, 45, 58, 0.12);
}

.fg-about-badge__logo {
  display: flex;
  align-items: center;
  height: 44px;
  margin-bottom: 0.75rem;
}

.fg-about-badge__logo img {
  width: auto;
  height: auto;
  max-width: 128px;
  max-height: 44px;
  object-fit: contain;
}

.fg-about-badge strong {
  display: block;
  font-size: 0.98rem;
  font-weight: 800;
}

.fg-about-badge__copy {
  display: block;
  margin-top: 0.3rem;
  color: rgba(6, 33, 42, 0.72);
  font-size: 0.88rem;
  line-height: 1.5;
}

.fg-about-trust__note {
  max-width: 78ch;
  margin: clamp(1rem, 2vw, 1.4rem) 0 1.1rem;
  color: rgba(6, 33, 42, 0.78);
  font-size: 0.94rem;
}

/* Visit */
.fg-about-visit__grid {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: clamp(1.5rem, 3vw, 2.6rem);
  align-items: center;
}

.fg-about-visit__media {
  aspect-ratio: 3 / 2;
  background: var(--color-steel);
}

.fg-about-visit__address {
  display: grid;
  margin: 0 0 0.6rem;
  font-style: normal;
  font-size: 0.98rem;
  line-height: 1.5;
}

.fg-about-visit__hours {
  color: rgba(6, 33, 42, 0.72);
  font-size: 0.9rem;
}

/* Routes: compact text cards, no images needed. */
.fg-about-routes__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-about-route {
  display: block;
  height: 100%;
  padding: 0.95rem 1.1rem;
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.9);
  color: inherit;
  text-decoration: none;
  transition: border-color 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}

.fg-about-route:hover,
.fg-about-route:focus-visible {
  border-color: var(--color-accent);
  transform: translateY(-2px);
  box-shadow: 0 14px 32px rgba(0, 45, 58, 0.1);
}

.fg-about-route strong {
  display: block;
  font-size: 0.98rem;
  font-weight: 800;
}

.fg-about-route span {
  display: block;
  margin-top: 0.2rem;
  color: rgba(6, 33, 42, 0.7);
  font-size: 0.88rem;
  line-height: 1.45;
}

.fg-about-route--primary {
  border-color: var(--color-accent);
  background: #ffffff;
  box-shadow: 0 12px 28px rgba(46, 172, 102, 0.14);
}

@media (max-width: 1040px) {
  .fg-about-founders__grid {
    grid-template-columns: minmax(0, 1fr) minmax(0, 21rem);
  }

  .fg-about-trust__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  .fg-about section {
    padding: clamp(1.75rem, 6vw, 2.4rem) 0;
  }

  .fg-about h1,
  .fg-about h2,
  .fg-about p {
    max-width: none;
  }

  .fg-about-hero__grid,
  .fg-about-pricing__grid,
  .fg-about-founders__grid,
  .fg-about-award__grid,
  .fg-about-visit__grid {
    grid-template-columns: 1fr;
  }

  /* Copy first on mobile: the panel returns to DOM order below the copy. */
  .fg-about-pricing__panel {
    order: 0;
  }

  .fg-about-award__media {
    max-width: 26rem;
  }

  .fg-about-facts__strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .fg-about-facts__item:nth-child(odd) {
    border-left: 0;
  }

  .fg-about-facts__item:nth-child(n + 3) {
    border-top: 1px solid var(--color-line);
  }

  /* Two columns, lead spans the full width and stays first. */
  .fg-about-work__mosaic {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-auto-rows: clamp(8rem, 30vw, 10rem);
  }

  .fg-about-cell--lead {
    grid-column: span 2;
    grid-row: span 1;
  }

  .fg-about-founders__people {
    max-width: 24rem;
  }

  .fg-about-routes__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 560px) {
  .fg-about-pricing__panel {
    grid-template-columns: 1fr;
  }

  .fg-about-routes__grid {
    grid-template-columns: 1fr;
  }

  .fg-about-trust__grid {
    grid-template-columns: 1fr;
  }

  /* Stacked full-width actions read better than two cramped side-by-side
     buttons at phone widths. */
  .fg-about .button-row {
    flex-direction: column;
    align-items: stretch;
  }

  .fg-about .button-row .button {
    width: 100%;
  }
}

@media (max-width: 430px) {
  .fg-about-facts__strip {
    grid-template-columns: 1fr;
  }

  .fg-about-facts__item {
    border-left: 0;
  }

  .fg-about-facts__item + .fg-about-facts__item {
    border-top: 1px solid var(--color-line);
  }
}

@media (prefers-reduced-motion: reduce) {
  .fg-about-cell img,
  .fg-about-route,
  .fg-about-badge {
    transition: none;
  }

  .fg-about-cell:hover img,
  .fg-about-cell:focus-within img,
  .fg-about-route:hover,
  .fg-about-route:focus-visible,
  .fg-about-badge:hover,
  .fg-about-badge:focus-visible {
    transform: none;
  }
}

.fg-enquiry {
  padding: 5rem 0;
  color: #ffffff;
  background:
    linear-gradient(135deg, rgba(0, 45, 58, 0.96), rgba(0, 45, 58, 0.88)),
    var(--color-steel);
}

.fg-enquiry .eyebrow {
  color: var(--color-accent);
}

.fg-enquiry h2 {
