  font-size: clamp(2.5rem, 4.4vw, var(--fg-font-size-max));
}

.fg-enquiry__grid {
  display: grid;
  grid-template-columns: minmax(360px, 0.78fr) minmax(620px, 1.22fr);
  gap: var(--fg-space-5);
  align-items: stretch;
}

.fg-enquiry__copy,
.fg-form {
  padding: clamp(1.4rem, 3vw, 2.5rem);
