  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.fg-home-hero__quote-card strong {
  font-size: 1.55rem;
  line-height: 1.05;
}

.fg-home-hero__quote-card small {
  color: rgba(255, 255, 255, 0.76);
  line-height: 1.35;
}

.fg-home-hero__quote-card b {
  width: fit-content;
  color: #ffffff;
  border-bottom: 2px solid var(--color-accent);
}

.fg-home-hero__copy h1 {
  max-width: 820px;
  margin-bottom: 1.2rem;
  color: #ffffff;
  font-size: clamp(2.65rem, 4.25vw, var(--fg-font-size-max));
  line-height: 0.98;
}

.fg-home-hero__copy > p:not(.eyebrow) {
  max-width: 760px;
  color: rgba(255, 255, 255, 0.9);
  font-size: 1.22rem;
}

.fg-home-hero__panel {
  display: grid;
  gap: 0.55rem;
  padding: 1.2rem;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.12);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.22);
  backdrop-filter: blur(18px);
}

.fg-home-hero__panel span,
.fg-home-hero__panel a {
  color: var(--color-accent);
  font-weight: 800;
  text-decoration: none;
}

.fg-home-hero__panel strong {
  color: #ffffff;
  font-size: 2rem;
  line-height: 1;
}

.fg-home-hero__panel p {
  margin: 0;
  color: rgba(255, 255, 255, 0.82);
}

.fg-home-proof-wall {
  position: relative;
  z-index: 2;
  padding: 1.5rem 0 0.75rem;
  border-bottom: 0;
  background: transparent;
}

.fg-home-product-flow {
  position: relative;
  background: transparent;
}

.fg-home-product-flow > section {
  background: transparent;
}

.fg-home-proof-wall__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.8rem;
}

.fg-home-proof-wall__link {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  justify-content: center;
  margin-top: 0.85rem;
}

.fg-home-proof-wall__link a {
  display: inline-flex;
  gap: 0.4rem;
  align-items: center;
  min-height: 38px;
  padding: 0.45rem 0.72rem;
  border: 1px solid rgba(11, 61, 74, 0.14);
  border-radius: var(--fg-tag-radius);
  background: rgba(255, 255, 255, 0.68);
  color: var(--color-steel);
  font-size: var(--fg-tag-size);
  font-weight: var(--fg-tag-weight);
  line-height: 1.2;
  text-decoration: none;
  box-shadow: 0 10px 24px rgba(0, 45, 58, 0.06);
  backdrop-filter: blur(10px);
}

.fg-home-proof-wall__link a::after {
  content: "\2192";
  color: var(--color-accent);
  font-size: 0.95rem;
  line-height: 1;
  transition: transform 180ms ease;
}

.fg-home-proof-wall__link a:hover::after,
.fg-home-proof-wall__link a:focus-visible::after {
  transform: translateX(3px);
}

.fg-home-trust-card {
  display: grid;
  grid-template-columns: 88px minmax(0, 1fr);
  gap: 0.85rem;
  align-items: center;
  min-height: 126px;
  padding: 1rem;
  border: 1px solid rgba(0, 45, 58, 0.12);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 14px 34px rgba(0, 45, 58, 0.08);
  backdrop-filter: blur(12px);
}

.fg-home-trust-card img {
  width: 88px;
  height: 68px;
  object-fit: contain;
}

.fg-home-trust-card div {
  display: grid;
  gap: var(--fg-space-1);
}

.fg-home-trust-card strong {
  color: var(--color-steel);
  font-size: 1.12rem;
  line-height: 1.08;
}

.fg-home-trust-card span {
  color: var(--color-muted);
  font-size: var(--fg-text-md);
  line-height: 1.35;
}

.fg-review-showcase {
  padding: clamp(3.2rem, 6vw, 5.4rem) 0;
  overflow: hidden;
  background: transparent;
  color: #111827;
}

/* Shared star rendering: half-step fills, gold on light surfaces. */
.fg-stars {
  display: inline-flex;
  gap: 0.12em;
  font-size: var(--fg-text-base);
  line-height: 1;
}

.fg-stars--lg {
  font-size: 1.45rem;
}

.fg-stars__star {
  position: relative;
  width: 1em;
  height: 1em;
  background: #dfe4e6;
  -webkit-mask: var(--fg-star-mask) center / contain no-repeat;
  mask: var(--fg-star-mask) center / contain no-repeat;
}

.fg-stars__star.is-full {
  background: #f5a623;
}

.fg-stars__star.is-half {
  background: linear-gradient(90deg, #f5a623 50%, #dfe4e6 50%);
}

/* Copy left, both platforms in one proof cluster right. The score used to sit
   in its own tinted, padded box inside this white panel: a card inside a card,
   which STYLE.md forbids, and the main reason the panel read as bulky. The
   shadow was also doing too much at 18px/44px. */
.fg-review-showcase__summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: clamp(1.25rem, 3vw, 2.75rem);
  align-items: center;
  margin-bottom: clamp(1.5rem, 2.6vw, 2.1rem);
  padding: clamp(1.1rem, 2vw, 1.55rem) clamp(1.2rem, 2.2vw, 1.85rem);
  border: 1px solid rgba(17, 24, 39, 0.09);
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 10px 28px rgba(0, 45, 58, 0.05);
}

.fg-review-showcase__proof {
  display: flex;
  gap: clamp(1rem, 2.4vw, 2rem);
  align-items: stretch;
}

/* Two matched platform blocks. Each links to its own platform and carries the
   same size of link, so neither reads as the primary action over the other. */
.fg-review-showcase__source {
  display: grid;
  align-content: space-between;
  justify-items: start;
  gap: 0.3rem;
  text-align: left;
  text-decoration: none;
}

.fg-review-showcase__score-row {
  display: inline-flex;
  gap: 0.6rem;
  align-items: center;
}

.fg-review-showcase__trustpilot {
  gap: 0.45rem;
  padding-left: clamp(1rem, 2.4vw, 2rem);
  border-left: 1px solid rgba(17, 24, 39, 0.1);
}

/* Sized against the 4.9 and its stars opposite. At 150px the lockup was the
   lighter half of the pair and the column read as a logo with a hole under it. */
.fg-review-showcase__trustpilot img {
  width: clamp(150px, 14vw, 186px);
  height: auto;
}

.fg-review-showcase__source-link {
  margin-top: 0.15rem;
  color: #1c6b50;
  font-size: var(--fg-text-sm);
  font-weight: 800;
}

.fg-review-showcase__source:hover .fg-review-showcase__source-link {
  text-decoration: underline;
}

.fg-review-showcase__score-value {
  color: var(--color-steel, #002d3a);
  font-size: clamp(2.2rem, 3.8vw, 2.7rem);
  font-weight: 800;
  line-height: 1;
}

.fg-review-showcase__score-meta {
  color: #4b5a63;
  font-size: var(--fg-text-sm);
  line-height: 1.4;
}

.fg-review-showcase__score-meta strong {
  color: #111827;
}

.fg-review-showcase__intro {
  min-width: 0;
}

.fg-review-showcase__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-bottom: 0.5rem;
  color: #5f6c75;
  font-size: var(--fg-text-xs);
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.fg-review-showcase__gmark {
  display: inline-flex;
  font-size: 1.02rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  text-transform: none;
}

.fg-review-showcase__gmark span:nth-child(1) { color: #4285f4; }
.fg-review-showcase__gmark span:nth-child(2) { color: #ea4335; }
.fg-review-showcase__gmark span:nth-child(3) { color: #fbbc05; }
.fg-review-showcase__gmark span:nth-child(4) { color: #4285f4; }
.fg-review-showcase__gmark span:nth-child(5) { color: #34a853; }
.fg-review-showcase__gmark span:nth-child(6) { color: #ea4335; }

.fg-review-showcase__intro h2 {
  margin: 0 0 0.4rem;
  color: var(--color-steel, #002d3a);
  font-size: clamp(1.35rem, 2vw, 1.75rem);
  line-height: 1.15;
}

.fg-review-showcase__intro p {
  max-width: 56ch;
  margin: 0;
  color: #5b6770;
  font-size: 0.97rem;
  line-height: 1.45;
}


.fg-review-showcase__write {
  color: #1c6b50;
  font-size: var(--fg-text-md);
  font-weight: 800;
  text-decoration: underline;
  text-underline-offset: 0.2em;
}

.fg-review-showcase__write:hover,
.fg-review-showcase__write:focus-visible {
  color: #14513c;
}

.fg-review-showcase__carousel {
  position: relative;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: var(--fg-space-3);
  align-items: center;
}

.fg-review-showcase__cards {
  display: grid;
  grid-auto-columns: minmax(268px, 1fr);
  grid-auto-flow: column;
  gap: var(--fg-space-4);
  padding: 0.35rem 0.2rem 0.7rem;
  overflow-x: auto;
  scroll-snap-type: x proximity;
  scrollbar-width: none;
}

.fg-review-showcase__cards::-webkit-scrollbar {
  display: none;
}

.fg-review-showcase__card {
  display: grid;
  align-content: start;
  gap: 0.6rem;
  min-height: 100%;
  padding: 1.15rem 1.2rem 1.25rem;
  border: 1px solid rgba(17, 24, 39, 0.1);
  border-radius: 8px;
  background: #ffffff;
  color: inherit;
  scroll-snap-align: start;
  text-decoration: none;
  box-shadow: 0 10px 26px rgba(0, 45, 58, 0.05);
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.fg-review-showcase__card:hover,
.fg-review-showcase__card:focus-visible {
  transform: translateY(-3px);
  border-color: rgba(28, 107, 80, 0.35);
  box-shadow: 0 18px 40px rgba(0, 45, 58, 0.1);
}

.fg-review-showcase__head {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: center;
}

.fg-review-showcase__avatar {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(145deg, #dff7eb, #c4edda);
  color: #177555;
  font-size: 1.05rem;
  font-weight: 800;
}

.fg-review-showcase__avatar--photo {
  object-fit: cover;
}

.fg-review-showcase__identity {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.fg-review-showcase__name {
  overflow: hidden;
  color: #111827;
  font-size: 0.98rem;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.fg-review-showcase__date {
  color: #7d878f;
  font-size: 0.82rem;
}

.fg-review-showcase__glyph {
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: #f2f5f7;
  color: #4285f4;
  font-size: var(--fg-text-md);
  font-weight: 800;
}

.fg-review-showcase__glyph--trustpilot {
  background: #00b67a;
  color: #ffffff;
}

.fg-review-showcase__card p {
  margin: 0;
  color: #5b6770;
  font-size: 0.97rem;
  line-height: 1.5;
  /* Keep every card the same shape; the full review is one tap away. */
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 6;
  overflow: hidden;
}

.fg-review-showcase__read {
  margin-top: 0.15rem;
  color: #1c6b50;
  font-size: 0.88rem;
  font-weight: 800;
}

.fg-review-showcase__button {
  display: grid;
  place-items: center;
  width: 44px;
  height: 44px;
  border: 1px solid rgba(17, 24, 39, 0.12);
  border-radius: 50%;
  background: #ffffff;
  color: #111827;
  cursor: pointer;
  box-shadow: 0 8px 20px rgba(0, 45, 58, 0.08);
  transition: background 160ms ease, transform 160ms ease;
}

.fg-review-showcase__button:hover {
  background: #f3f8f6;
  transform: scale(1.05);
}

.fg-review-showcase__button::before {
  content: "";
  width: 10px;
  height: 10px;
  border: 2px solid currentColor;
  border-width: 2px 2px 0 0;
}

.fg-review-showcase__button--prev::before {
  transform: rotate(-135deg) translate(-2px, -2px);
}

.fg-review-showcase__button--next::before {
  transform: rotate(45deg) translate(-2px, -2px);
}

.fg-home-system-panel {
  padding: 6.5rem 0;
  overflow: hidden;
  background: transparent;
  color: var(--color-ink);
}

.fg-home-system-panel__head {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(280px, 0.56fr);
  gap: var(--fg-space-6);
  align-items: end;
  margin-bottom: 1.2rem;
}

.fg-home-system-panel__head .eyebrow {
  grid-column: 1 / -1;
  color: var(--color-accent);
}

.fg-home-system-panel__head h2 {
  max-width: 760px;
  color: var(--color-steel);
  font-size: clamp(2.1rem, 3.2vw, 3rem);
  line-height: 1;
}

.fg-home-system-panel__head p:not(.eyebrow) {
  max-width: 470px;
  color: var(--color-muted);
  font-size: 1.08rem;
}

.fg-home-system-panel__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--fg-space-4);
}

.fg-home-system-card {
  position: relative;
  display: grid;
  align-content: end;
  min-height: 340px;
  padding: 1.15rem;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 8px;
  color: #ffffff;
  text-decoration: none;
  background: #0b3039;
  box-shadow: 0 22px 64px rgba(0, 0, 0, 0.22);
}

.fg-home-system-card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 280ms ease;
}

.fg-home-system-card::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(0deg, rgba(0, 24, 31, 0.3), rgba(0, 24, 31, 0.02) 62%),
    linear-gradient(90deg, rgba(0, 45, 58, 0.1), transparent);
  transition: background 180ms ease;
}

.fg-home-system-card:hover::after,
.fg-home-system-card:focus-visible::after {
  background:
    linear-gradient(0deg, rgba(0, 24, 31, 0.72), rgba(0, 24, 31, 0.26) 68%),
    linear-gradient(90deg, rgba(0, 45, 58, 0.42), transparent);
}

.fg-home-system-card strong,
.fg-home-system-card small {
  position: relative;
  z-index: 1;
}

.fg-home-system-card strong {
  max-width: 560px;
  color: #ffffff;
  font-size: 1.5rem;
  line-height: 1.02;
}

.fg-home-system-card small {
  max-width: 560px;
  margin-top: 0.6rem;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.98rem;
}

.fg-home-system-card:hover img,
.fg-home-system-card:focus-visible img {
  transform: scale(1.045);
}

.fg-home-product-story {
  padding: clamp(2.25rem, 4vw, 3.5rem) 0 2rem;
  background: transparent;
}

.fg-home-product-story__head {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(280px, 0.56fr);
  gap: var(--fg-space-6);
  align-items: end;
  margin-bottom: clamp(1.5rem, 3vw, 2.5rem);
}

.fg-home-product-story__head .eyebrow {
  grid-column: 1 / -1;
  color: var(--color-accent);
}

.fg-home-product-story__head h2 {
  max-width: 760px;
  color: var(--color-steel);
  font-size: clamp(2.1rem, 3.2vw, 3rem);
  line-height: 1;
}

.fg-home-product-story__head p:not(.eyebrow) {
  max-width: 500px;
  color: var(--color-muted);
  font-size: 1.08rem;
}

.fg-home-product-story__layout {
  display: grid;
  grid-template-columns: minmax(0, 1.08fr) minmax(360px, 0.72fr);
  gap: clamp(1.5rem, 4vw, 4rem);
  align-items: start;
}

.fg-home-product-story__stage {
  position: sticky;
  top: 96px;
}

.fg-home-product-story__images {
  position: relative;
  display: block;
  min-height: min(70svh, 680px);
  overflow: hidden;
  border-radius: 10px;
  background: var(--color-steel);
  color: #ffffff;
  text-decoration: none;
  box-shadow: 0 28px 80px rgba(0, 45, 58, 0.2);
}

.fg-home-product-story__images > img,
.fg-home-product-story__shade {
  position: absolute;
  inset: 0;
}

.fg-home-product-story__images > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transform: scale(1.08);
  transition: opacity 520ms ease, transform 900ms cubic-bezier(0.2, 0.75, 0.25, 1);
}

.fg-home-product-story__images > img.is-active {
  opacity: 1;
  transform: scale(1);
}

.fg-home-product-story__shade {
  z-index: 1;
  background:
    linear-gradient(0deg, rgba(0, 31, 39, 0.72), transparent 54%),
    linear-gradient(90deg, rgba(0, 45, 58, 0.18), transparent 55%);
}

.fg-home-product-story__stage-copy {
  position: absolute;
  z-index: 2;
  left: clamp(1rem, 3vw, 2rem);
  right: clamp(1rem, 3vw, 2rem);
  bottom: clamp(1rem, 3vw, 2rem);
  display: grid;
  gap: 0.55rem;
}

.fg-home-product-story__stage-copy > span {
  width: fit-content;
  margin-top: 0.25rem;
  padding-bottom: 0.15rem;
  border-bottom: 2px solid var(--color-accent);
  color: var(--color-accent);
  font-size: 0.9rem;
  font-weight: 800;
}

.fg-home-product-story__stage-copy strong {
  color: #ffffff;
  font-size: clamp(2rem, 4vw, var(--fg-font-size-max));
  line-height: 0.96;
}

.fg-home-product-story__stage-copy p {
  max-width: 560px;
  margin: 0;
  color: rgba(255, 255, 255, 0.84);
  font-size: clamp(1rem, 1.4vw, 1.15rem);
}

.fg-home-product-story__progress {
  height: 4px;
  margin-top: 0.8rem;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(0, 45, 58, 0.12);
}

.fg-home-product-story__progress span {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: var(--color-accent);
  transform: scaleX(0.125);
  transform-origin: left;
  transition: transform 420ms cubic-bezier(0.2, 0.75, 0.25, 1);
}

.fg-home-product-story__steps {
  display: grid;
  gap: clamp(1rem, 3vh, 1.75rem);
  padding: 3vh 0 72vh;
}

.fg-home-product-step {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 0;
  align-items: start;
  min-height: 168px;
  padding: 1.25rem;
  border: 1px solid rgba(0, 45, 58, 0.11);
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.58);
  color: var(--color-ink);
  text-decoration: none;
  opacity: 0.58;
  transform: translateX(18px);
  transition: opacity 260ms ease, transform 360ms ease, background 260ms ease, box-shadow 260ms ease;
}

.fg-home-product-step.is-active,
.fg-home-product-step:hover,
.fg-home-product-step:focus-visible {
  opacity: 1;
  transform: translateX(0);
  border-color: rgba(0, 45, 58, 0.18);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: 0 22px 58px rgba(0, 45, 58, 0.13);
}

.fg-home-product-step > img {
  display: none;
}

.fg-home-product-step div {
  display: grid;
  gap: 0.85rem;
}

.fg-home-product-step strong {
  color: var(--color-steel);
  font-size: clamp(1.45rem, 2vw, 1.9rem);
  line-height: 1.04;
}

.fg-home-product-step small {
  position: relative;
  width: fit-content;
  padding-right: 1.45rem;
  color: var(--color-steel);
  font-size: 0.9rem;
  font-weight: 800;
}

.fg-home-product-step small::after {
  content: "â†’";
  position: absolute;
  right: 0;
  color: var(--color-accent);
  transition: transform 180ms ease;
}

.fg-home-product-step:hover small::after,
.fg-home-product-step:focus-visible small::after {
  transform: translateX(3px);
}

.fg-home-product-step dl {
