@media (max-width: 860px) {
  :root {
    --site-header-main-height: 76px;
  }

  html.is-mobile-nav-open,
  html.is-mobile-nav-open body {
    overflow: hidden;
  }

  /* THE LAUNCHER CANNOT SIT ON TOP OF THE DRAWER AND STILL BE DEAD.

     `src/js/main.js` marks `[data-legend-assistant]` inert while the drawer is
     open, which is right: the drawer is an opaque full-screen overlay and the
     page behind it must leave the tab order. But `.legend-assistant` is
     `position: fixed; z-index: 1100` globally, against `.site-header`'s 1000 in
     this media query, so the launcher floats above the overlay. Without this it
     is visible and refuses every tap. Hidden rather than restacked, which is the
     same treatment `.legend-assistant.is-cookie-modal-open` already gets for the
     same reason, and it reuses the opacity/visibility transition already
     declared on the wrapper. */
  html.is-mobile-nav-open .legend-assistant {
    visibility: hidden;
    opacity: 0;
  }

  .site-header {
    position: fixed;
    top: 0;
    right: 0;
    left: 0;
    width: 100%;
    z-index: 1000;
    isolation: isolate;
    transform: translateZ(0);
  }

  .site-header.is-nav-open {
    bottom: 0;
    height: 100svh;
  }

  .site-main {
    padding-top: var(--site-header-main-height);
  }

  .site-header__inner {
    min-height: var(--site-header-main-height);
    align-items: center;
    flex-direction: row;
    flex-wrap: wrap;
  }

  .site-header__phone {
    display: none;
  }

  .site-header__mobile-call {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.35rem;
    min-height: 46px;
    margin-left: auto;
    padding: 0.55rem 0.8rem;
    border: 1px solid var(--color-accent-dark);
    border-radius: 999px;
    background: var(--color-accent);
    color: #ffffff;
    font-size: 0.9rem;
    font-weight: 800;
    line-height: 1;
    text-decoration: none;
    white-space: nowrap;
  }

  .site-header__mobile-call-icon {
    width: 1rem;
    height: 1rem;
    flex: 0 0 1rem;
    fill: currentColor;
  }

  .site-footer__grid,
  .fg-proof-strip__inner,
  .fg-partners,
  .fg-designer-cta__grid,
  .fg-home-proof__grid,
  .fg-home-parallax__grid,
  .fg-home-quote-lab__grid,
  .fg-home-final__grid {
    grid-template-columns: 1fr;
  }

  .site-nav-toggle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 62px;
    margin-left: 0;
    min-height: 46px;
    border-color: rgba(0, 45, 58, 0.16);
    border-radius: 999px;
    transition: background 180ms ease, color 180ms ease, border-color 180ms ease;
  }

  .site-header.is-nav-open .site-nav-toggle {
    border-color: var(--color-steel);
    background: var(--color-steel);
    color: #ffffff;
  }

  .site-nav-toggle:focus-visible,
  .site-header__mobile-call:focus-visible,
  .site-mobile-nav__row:focus-visible,
  .site-mobile-nav__panel--links a:focus-visible,
  .site-mobile-nav__intro > a:focus-visible {
    outline: 3px solid var(--color-accent);
    outline-offset: 2px;
  }

  .site-nav {
    display: none;
    position: fixed;
    top: var(--site-header-main-height);
    left: 0;
    right: 0;
    z-index: 1001;
    width: auto;
    max-width: 100%;
    height: calc(100svh - var(--site-header-main-height));
    min-height: 0;
    margin-left: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    background:
      radial-gradient(circle at 100% 0%, rgba(46, 172, 102, 0.12), transparent 34%),
      #eef3f2;
  }

  .site-header.is-nav-open .site-nav {
    display: block;
  }

  .site-nav__list {
    display: none;
  }

  .site-mobile-nav {
    display: grid;
    align-content: start;
    gap: 0.65rem;
    width: 100%;
    min-height: 100%;
    margin: 0;
    padding: 0.8rem;
    background: transparent;
    color: var(--color-steel);
  }

  .site-mobile-nav__intro {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: var(--fg-space-4);
    align-items: center;
    padding: 1rem;
    border-radius: 18px;
    background:
      radial-gradient(circle at 95% 0%, rgba(46, 172, 102, 0.54), transparent 38%),
      var(--color-steel);
    color: #ffffff;
    box-shadow: 0 16px 34px rgba(0, 45, 58, 0.16);
  }

  .site-mobile-nav__intro > div {
    display: grid;
    gap: 0.15rem;
  }

  .site-mobile-nav__intro > div span {
    color: #77d79f;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.09em;
    text-transform: uppercase;
  }

  .site-mobile-nav__intro strong {
    max-width: 13ch;
    color: #ffffff;
    font-size: 1.16rem;
    line-height: 1.05;
  }

  .site-mobile-nav__intro > a {
    display: inline-flex;
    min-height: 42px;
    align-items: center;
    gap: 0.55rem;
    padding: 0.65rem 0.78rem;
    border-radius: 999px;
    background: var(--color-accent);
    color: #ffffff;
    font-size: 0.75rem;
    font-weight: 800;
    line-height: 1;
    text-decoration: none;
  }

  .site-mobile-nav__intro > a span {
    font-size: var(--fg-text-base);
  }

  .site-mobile-nav__item {
    margin: 0;
    overflow: hidden;
    border: 1px solid rgba(0, 45, 58, 0.1);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 8px 22px rgba(0, 45, 58, 0.06);
  }

  .site-mobile-nav__item.is-open {
    border-color: rgba(46, 172, 102, 0.4);
    background: #ffffff;
  }

  .site-mobile-nav__item--child {
    border: 0;
    border-radius: 10px;
    background: #f1f5f4;
    box-shadow: none;
  }

  .site-mobile-nav__row {
    display: flex;
    width: 100%;
    min-height: 56px;
    align-items: center;
    justify-content: space-between;
    gap: var(--fg-space-4);
    padding: 0.8rem 1rem;
    border: 0;
    background: transparent;
    color: var(--color-steel);
    font: inherit;
    font-size: 1.02rem;
    font-weight: 800;
    line-height: 1.1;
    text-align: left;
    text-decoration: none;
  }

  .site-mobile-nav__row > span:first-child {
    min-width: 0;
  }

  .site-mobile-nav__row > span[aria-hidden="true"] {
    position: relative;
    width: 30px;
    height: 30px;
    flex: 0 0 auto;
    border-radius: 999px;
    background: #edf4f1;
  }

  .site-mobile-nav__row > span[aria-hidden="true"]::before,
  .site-mobile-nav__row > span[aria-hidden="true"]::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 12px;
    height: 2px;
    border-radius: 999px;
    background: currentColor;
    transform: translate(-50%, -50%);
  }

  .site-mobile-nav__row > span[aria-hidden="true"]::after {
    transform: translate(-50%, -50%) rotate(90deg);
  }

  .site-mobile-nav__item.is-open > .site-mobile-nav__row > span[aria-hidden="true"]::after {
    display: none;
  }

  .site-mobile-nav__item.is-open > .site-mobile-nav__row > span[aria-hidden="true"] {
    background: rgba(46, 172, 102, 0.14);
    color: var(--color-accent-dark);
  }

  .site-mobile-nav__panel {
    display: none;
  }

  .site-mobile-nav__item.is-open > .site-mobile-nav__panel {
    display: grid;
  }

  .site-mobile-nav__item > .site-mobile-nav__panel {
    gap: var(--fg-space-2);
    padding: 0 0.65rem 0.65rem;
  }

  .site-mobile-nav__item--child > .site-mobile-nav__row {
    min-height: 48px;
    padding: 0.6rem 0.75rem;
    font-size: 0.93rem;
  }

  .site-mobile-nav__item--child.is-open {
    background: #e5f1eb;
  }

  .site-mobile-nav__item--child.is-open > .site-mobile-nav__row {
    padding-bottom: 0.45rem;
  }

  .site-mobile-nav__panel--links {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.45rem;
    padding: 0.1rem 0.65rem 0.75rem;
  }

  .site-mobile-nav__panel--links a {
    position: relative;
    display: flex;
    min-width: 0;
    min-height: 44px;
    align-items: center;
    padding: 0.62rem 1.65rem 0.62rem 0.7rem;
    border: 1px solid rgba(0, 45, 58, 0.08);
    border-radius: 9px;
    background: rgba(255, 255, 255, 0.86);
    color: var(--color-steel);
    font-size: 0.82rem;
    font-weight: 700;
    line-height: 1.12;
    text-decoration: none;
  }

  .site-mobile-nav__panel--links a::after {
    content: "\2192";
    position: absolute;
    right: 0.65rem;
    color: var(--color-accent-dark);
    font-size: var(--fg-text-md);
  }

  .site-mobile-nav > .site-mobile-nav__row--link {
    position: relative;
    padding: 0.8rem 3.75rem 0.8rem 1rem;
    border: 1px solid rgba(0, 45, 58, 0.1);
    border-radius: 14px;
    background: rgba(255, 255, 255, 0.9);
    box-shadow: 0 8px 22px rgba(0, 45, 58, 0.06);
  }

  .site-mobile-nav > .site-mobile-nav__row--link::after {
    content: "\2192";
    position: absolute;
    top: 50%;
    right: 1rem;
    display: grid;
    width: 30px;
    height: 30px;
    place-items: center;
    border-radius: 999px;
    background: #edf4f1;
    color: var(--color-accent-dark);
    font-size: var(--fg-text-md);
    line-height: 1;
    transform: translateY(-50%);
  }

  .site-mobile-nav > .site-mobile-nav__row--quote {
    border-color: var(--color-accent);
    background: var(--color-accent);
    color: #ffffff;
  }

  .site-mobile-nav > .site-mobile-nav__row--quote::after {
    background: rgba(255, 255, 255, 0.18);
    color: #ffffff;
  }

  /* Matches .site-nav__consultation on desktop: the dark steel half of the
     green-then-dark pair the header uses. */
  .site-mobile-nav > .site-mobile-nav__row--consultation {
    border-color: var(--color-steel);
    background: var(--color-steel);
    color: #ffffff;
  }

  .site-mobile-nav > .site-mobile-nav__row--consultation::after {
    background: rgba(255, 255, 255, 0.18);
    color: #ffffff;
  }

  .site-nav__quote > a {
    width: auto;
    margin: 0.35rem 0 0;
    padding-inline: 1rem;
  }

