/* Integral blinds: desktop scroll-controlled chroma reveal. */
html.fg-blinds-reveal-locked {
  overflow: hidden;
}

.fg-integral-blinds-reveal {
  position: fixed;
  inset: 0;
  z-index: 45;
  overflow: hidden;
  pointer-events: none;
  background: transparent;
  opacity: 0;
  visibility: hidden;
  transition: opacity 120ms linear, visibility 0s linear 120ms;
}

.fg-integral-blinds-reveal.is-ready {
  opacity: 1;
  visibility: visible;
  transition: opacity 120ms linear;
}

.fg-integral-blinds-reveal.is-complete {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.fg-integral-blinds-reveal__canvas {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: right center;
  opacity: var(--fg-blinds-opacity, 1);
}

.fg-integral-blinds-reveal__video {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
  pointer-events: none;
}

.fg-integral-blinds-reveal__cue {
  position: absolute;
  left: 50%;
  bottom: clamp(1.25rem, 4vh, 2.75rem);
  display: grid;
  gap: 0.6rem;
  width: min(240px, calc(100vw - 3rem));
  color: #fff;
  font-size: var(--fg-text-2xs);
  font-weight: 800;
  letter-spacing: 0.12em;
  text-align: center;
  text-transform: uppercase;
  text-shadow: 0 1px 12px rgba(0, 0, 0, 0.75);
  transform: translateX(-50%);
  opacity: var(--fg-blinds-cue-opacity, 1);
}

.fg-integral-blinds-reveal__cue i {
  display: block;
  height: 3px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.28);
  overflow: hidden;
}

.fg-integral-blinds-reveal__cue i::after {
  display: block;
  width: 100%;
  height: 100%;
  background: var(--colour-accent, #2fb66d);
  content: "";
  transform: scaleX(var(--fg-blinds-progress, 0));
  transform-origin: left center;
}

@media (max-width: 860px), (prefers-reduced-motion: reduce) {
  .fg-integral-blinds-reveal {
    display: none;
  }
}

