}

.fg-contact-showroom__grid {
  display: grid;
  grid-template-columns: minmax(380px, 0.48fr) minmax(520px, 1fr);
  gap: clamp(1rem, 3vw, 2rem);
  align-items: stretch;
}

.fg-contact-showroom__copy {
  display: grid;
  align-content: center;
  gap: 0.85rem;
  padding: clamp(1.25rem, 3vw, 2.3rem);
