  box-shadow: 0 24px 58px rgba(0, 45, 58, 0.14);
}

.fg-contact-showroom__map iframe {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 540px;
}

.fg-contact-route__layout {
  display: grid;
  grid-template-columns: minmax(280px, 0.36fr) minmax(0, 1fr);
  gap: clamp(1rem, 3vw, 2.25rem);
