}

.fg-contact-route__rows {
  display: grid;
  gap: var(--fg-space-3);
}

.fg-contact-route-row {
  position: relative;
  display: grid;
  grid-template-columns: minmax(130px, 0.22fr) minmax(220px, 0.34fr) minmax(0, 1fr);
  gap: clamp(0.9rem, 2vw, 1.4rem);
