  }

  .fg-commercial-product-hero__shade {
    background:
      linear-gradient(0deg, rgba(0, 45, 58, 0.92), rgba(0, 45, 58, 0.5)),
      linear-gradient(90deg, rgba(0, 45, 58, 0.76), rgba(0, 45, 58, 0.34));
  }

  .fg-commercial-product-hero__inner,
  .fg-commercial-product-intro__grid,
  .fg-commercial-product-fit__grid,
  .fg-commercial-product-detail,
  .fg-commercial-product-detail--flip {
    grid-template-columns: 1fr;
  }

  .fg-commercial-product-hero__inner {
    padding: 7rem 0 2rem;
  }

  .fg-commercial-product-hero h1 {
    font-size: clamp(2.35rem, 12vw, var(--fg-font-size-max));
  }

  .fg-commercial-product-hero__stats {
    grid-template-columns: 1fr;
  }

  .fg-commercial-product-checks__grid,
  .fg-commercial-product-related__grid {
    grid-template-columns: 1fr;
  }

  .fg-commercial-product-checks__grid article {
    min-height: 0;
  }

  .fg-commercial-product-detail--flip figure {
    order: 0;
  }

  .fg-commercial-product-detail img,
  .fg-commercial-product-detail > div {
    min-height: 0;
  }

  /* Spec table and proof band, added with the 2026-08-12 commercial rework.
     The spec grid drops to one column of rows; the ROW itself keeps its two
     columns down to 560px, because label-left / value-right is what makes it
     scan like a schedule and stacking it doubles the height for nothing. */
  .fg-cm-spec__grid {
    grid-template-columns: 1fr;
  }

  /* `minmax(0, 1fr)`, NOT a bare `1fr`. A bare `1fr` carries an implicit auto
     minimum, so the column sizes to its content rather than to the viewport:
     measured at 390px the proof card resolved to 532px inside a 366px container
     and was clipped by `body { overflow-x: clip }`, which meant the page
     reported no horizontal scroll while a third of every card was invisible.
     The same trap is already recorded against the colour rail in `AI.md`. */
  .fg-cm-proof__grid,
  .fg-cm-creds__list {
    grid-template-columns: minmax(0, 1fr);
  }

  .fg-cm-placeholder {
    min-height: 0;
  }
}

@media (max-width: 560px) {
  /* Below this the value column gets too narrow to read a sentence in, so the
     row stacks. Checked at 390px: the longest value is the AOV scope line and
     it wraps rather than overflowing. */
  .fg-cm-spec__row {
    grid-template-columns: 1fr;
    gap: 0.3rem;
  }

  .fg-commercial-product-hero__actions,
  .fg-commercial-product-hero__actions .button,
  .fg-commercial-product-hero__phone {
    width: 100%;
  }

  .fg-commercial-product-hero__actions .button,
  .fg-commercial-product-hero__phone {
    justify-content: center;
    text-align: center;
  }

  .fg-commercial-product-intro,
  .fg-commercial-product-checks,
  .fg-commercial-product-details,
  .fg-commercial-product-fit,
  .fg-commercial-product-related {
    padding: 2.4rem 0;
  }

  .fg-commercial-product-detail > div {
    padding: 1rem;
  }
}

.fg-price-guide__hero {
  padding: clamp(2.5rem, 5vw, 4rem) 0 clamp(2rem, 4vw, 3rem);
}

.fg-price-guide__hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.46fr);
  gap: clamp(1.2rem, 3vw, 2.6rem);
  align-items: center;
}

.fg-price-guide__hero-copy h1 {
  max-width: 14ch;
  margin: 0.45rem 0 0.9rem;
  color: var(--color-steel);
}

.fg-price-guide__hero-copy > p:not(.eyebrow) {
  max-width: 46ch;
  margin: 0 0 1.2rem;
  font-size: clamp(1.02rem, 1.2vw, 1.1rem);
  line-height: 1.6;
}

/* At-a-glance card: the checked prices, scannable before anything else. */
.fg-price-guide__glance {
  padding: 1.35rem 1.4rem 1.25rem;
  border: 1px solid var(--color-line);
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 24px 56px rgba(0, 45, 58, 0.1);
}

.fg-price-guide__glance > strong {
  display: block;
  margin-bottom: 0.75rem;
  color: var(--color-accent-dark);
  font-size: var(--fg-text-xs);
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.fg-price-guide__glance ul {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-price-guide__glance li {
  display: flex;
  gap: var(--fg-space-4);
  align-items: baseline;
  justify-content: space-between;
  padding: 0.65rem 0;
  border-top: 1px solid var(--color-line);
}

.fg-price-guide__glance li span {
  font-size: var(--fg-text-md);
  font-weight: 600;
  line-height: 1.35;
}

.fg-price-guide__glance li em {
  color: var(--color-steel);
  font-size: 1.02rem;
  font-style: normal;
  font-weight: 800;
  white-space: nowrap;
}

.fg-price-guide__glance > p {
  margin: 0.8rem 0 0;
  color: rgba(6, 33, 42, 0.68);
  font-size: 0.84rem;
  line-height: 1.5;
}

/* Shared section rhythm */
.fg-price-guide__examples,
.fg-price-guide__factors,
.fg-price-guide__faq {
  padding: clamp(2rem, 4vw, 3rem) 0;
}

.fg-price-guide__section-head {
  max-width: 46rem;
  margin-bottom: clamp(1.25rem, 2.6vw, 2rem);
}

.fg-price-guide__section-head h2,
.fg-price-guide__factors h2,
.fg-price-guide__faq h2 {
  max-width: 24ch;
  margin: 0.4rem 0 0.75rem;
  font-size: clamp(1.45rem, 2.2vw, 2rem);
  line-height: 1.12;
}

.fg-price-guide__section-head p:not(.eyebrow),
.fg-price-guide__factors-copy p:not(.eyebrow) {
  max-width: 56ch;
  margin: 0;
  font-size: clamp(1rem, 1.05vw, 1.06rem);
  line-height: 1.6;
}

/* Checked example rows: photo-led, alternating sides. */
.fg-price-guide__example-stack {
  display: grid;
  gap: clamp(1.25rem, 2.6vw, 2rem);
}

.fg-price-guide__example {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(1.25rem, 3vw, 2.5rem);
  align-items: center;
  padding: clamp(1.25rem, 2.4vw, 1.9rem);
  border: 1px solid var(--color-line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.92);
}

.fg-price-guide__example--reverse .fg-price-guide__example-copy {
  order: 2;
}

.fg-price-guide__example--reverse .fg-price-guide__example-media {
  order: 1;
}

.fg-price-guide__example-copy .eyebrow {
  margin: 0 0 0.5rem;
  color: var(--color-accent-dark);
  font-size: 0.74rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.fg-price-guide__example-copy h3 {
  margin: 0 0 0.55rem;
  font-size: clamp(1.2rem, 1.7vw, 1.5rem);
  line-height: 1.15;
}

.fg-price-guide__example-copy > p {
  max-width: 48ch;
  margin: 0 0 1rem;
  color: rgba(6, 33, 42, 0.78);
  font-size: 0.97rem;
  line-height: 1.55;
}

.fg-price-guide__price {
  display: inline-flex;
  gap: var(--fg-space-2);
  align-items: baseline;
  padding: 0.55rem 0.9rem;
  border-radius: 8px;
  background: rgba(46, 172, 102, 0.12);
  border: 1px solid rgba(46, 172, 102, 0.4);
  color: var(--color-steel);
  font-size: clamp(1.3rem, 1.9vw, 1.6rem);
  font-weight: 800;
  line-height: 1;
}

.fg-price-guide__price em {
  color: var(--color-accent-dark);
  font-size: var(--fg-text-xs);
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.fg-price-guide__example-copy small {
  display: block;
  margin-top: 0.6rem;
  color: rgba(6, 33, 42, 0.62);
  font-size: 0.84rem;
  line-height: 1.5;
}

/* The WindowCAD configuration behind a photographed example. */
.fg-price-guide__config {
  margin: 1rem 0 0;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: #ffffff;
  max-width: 24rem;
}

.fg-price-guide__config img {
  display: block;
  width: 100%;
  height: auto;
  max-height: 150px;
  object-fit: contain;
}

.fg-price-guide__config figcaption {
  margin-top: 0.45rem;
  color: rgba(6, 33, 42, 0.62);
  font-size: 0.74rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.fg-price-guide__example-media {
  position: relative;
  margin: 0;
  overflow: hidden;
  border-radius: 10px;
  background: var(--color-steel);
  aspect-ratio: 16 / 11;
}

.fg-price-guide__example-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* WindowCAD screenshots are white-background renders: contain them instead of
   cropping, on a white panel. */
.fg-price-guide__example-media--config {
  background: #ffffff;
  border: 1px solid var(--color-line);
}

.fg-price-guide__example-media--config img {
  padding: 1.25rem;
  object-fit: contain;
}

.fg-price-guide__example-media figcaption {
  position: absolute;
  bottom: 0.85rem;
  left: 0.85rem;
  padding: 0.3rem 0.55rem;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.92);
  color: var(--color-steel);
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Factors: copy beside a two-column checklist. */
.fg-price-guide__factors-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  gap: clamp(1.5rem, 3.4vw, 3rem);
  align-items: center;
}

.fg-price-guide__factors-copy .button-row {
  margin-top: 1.2rem;
}

.fg-price-guide__factor-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.fg-price-guide__factor-list li {
  position: relative;
  padding: 0.85rem 1rem 0.85rem 2.5rem;
  border: 1px solid var(--color-line);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.9);
  font-size: 0.93rem;
  font-weight: 600;
  line-height: 1.4;
}

.fg-price-guide__factor-list li::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0.9rem;
  width: 1.05rem;
  height: 1.05rem;
  border-radius: 50%;
  background:
    linear-gradient(transparent, transparent),
    var(--color-accent);
  transform: translateY(-50%);
}

.fg-price-guide__factor-list li::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 1.17rem;
  width: 0.32rem;
  height: 0.58rem;
  border-right: 2px solid #ffffff;
  border-bottom: 2px solid #ffffff;
  transform: translateY(-64%) rotate(45deg);
}

/* FAQ + quote station reuse shared component styling. */
.fg-price-guide__faq-grid {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: clamp(1.5rem, 3vw, 2.6rem);
  align-items: start;
}

.fg-price-guide__faq .fg-product-faq__items details {
  background: #ffffff;
}

.fg-price-guide__quote-station {
  margin-top: clamp(1rem, 2.5vw, 2rem);
}

@media (max-width: 1040px) {
  .fg-price-guide__hero-grid {
    grid-template-columns: 1fr;
  }

  .fg-price-guide__glance {
    max-width: 30rem;
  }
}

@media (max-width: 860px) {
  .fg-price-guide__factors-grid,
  .fg-price-guide__faq-grid {
    grid-template-columns: 1fr;
  }

  .fg-price-guide__example,
  .fg-price-guide__example--reverse {
    grid-template-columns: 1fr;
  }

  /* Photo first on mobile, copy beneath. */
  .fg-price-guide__example-media,
  .fg-price-guide__example--reverse .fg-price-guide__example-media {
    order: -1;
  }

  .fg-price-guide__example-copy,
  .fg-price-guide__example--reverse .fg-price-guide__example-copy {
    order: 0;
  }

  .fg-price-guide__hero {
    padding-top: clamp(1.75rem, 6vw, 2.4rem);
  }
}

@media (max-width: 560px) {
  .fg-price-guide__factor-list {
    grid-template-columns: 1fr;
  }

  .fg-price-guide__hero-copy .button-row,
  .fg-price-guide__factors-copy .button-row {
    flex-direction: column;
    align-items: stretch;
  }

  .fg-price-guide__hero-copy .button,
  .fg-price-guide__factors-copy .button {
    width: 100%;
  }

  .fg-price-guide__glance li {
    flex-direction: column;
    gap: 0.1rem;
  }
}

// Roof lanterns: a dedicated, image-led product journey rather than the shared product template.
.fg-roof-lantern-page {
  background: var(--fg-page-gradient);
  background-attachment: fixed;
  overflow: clip;

  h1,
  h2,
  h3,
  p {
    margin-top: 0;
  }
}

.fg-roof-lantern-hero {
  padding: clamp(2rem, 4vh, 3rem) 0;
}

.fg-roof-lantern-hero__grid,
.fg-roof-lantern-intro__grid,
.fg-roof-lantern-system__grid,
.fg-roof-lantern-enquiry__grid {
  display: grid;
  align-items: center;
  gap: clamp(2rem, 4vw, 4rem);
}

.fg-roof-lantern-hero__grid {
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
}

.fg-roof-lantern-hero__copy {
  padding: 0.75rem 0;
}

.fg-roof-lantern-hero h1 {
  max-width: 12ch;
  margin-bottom: 1rem;
  font-size: clamp(2.5rem, 3.6vw, 3.6rem);
  line-height: 0.98;
}

.fg-roof-lantern-hero__lead {
  max-width: 55ch;
  color: var(--color-muted);
  font-size: clamp(1.05rem, 1.3vw, 1.22rem);
  line-height: 1.58;
}

.fg-roof-lantern-hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--fg-space-4);
  margin: 1.5rem 0 1.25rem;
}

.fg-roof-lantern-hero__call {
  color: var(--color-ink);
  font-weight: 700;
  text-decoration: none;
}

.fg-roof-lantern-hero__call:hover {
  color: var(--color-accent-dark);
}

.fg-roof-lantern-hero__reassurance,
.fg-roof-lantern-enquiry__copy ul {
  display: grid;
  gap: 0.6rem;
  padding: 0;
  margin: 0;
  list-style: none;
}

.fg-roof-lantern-hero__reassurance li,
.fg-roof-lantern-enquiry__copy li {
  position: relative;
  padding-left: 1.45rem;
  color: var(--color-muted);
}

.fg-roof-lantern-hero__reassurance li::before,
.fg-roof-lantern-enquiry__copy li::before {
  position: absolute;
  top: 0.45em;
  left: 0;
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
  background: var(--color-accent);
  content: '';
}

/* A deeper shade for the lantern hero only. The shared gradient is tuned for
   brick and slate; this photograph is glass in full sun, and measured against
   it the mint eyebrow fell to about 1.7:1 and the white H1 to 3:1, which
   STYLE.md calls a release blocker rather than a nuance. Scoped to this route
   so the heroes that do not need it are untouched, and applied to the shade
   rather than the image so the photograph itself is not dulled where no text
   sits over it. */
.fg-roof-lantern-page .fg-hero__shade {
  background:
    linear-gradient(90deg, rgba(0, 45, 58, 0.76) 0%, rgba(0, 45, 58, 0.6) 46%, rgba(0, 45, 58, 0.16) 100%),
    linear-gradient(0deg, rgba(0, 45, 58, 0.6), rgba(0, 45, 58, 0.12) 54%);
}

/* The lead and the reassurance points, moved out of the hero when this route
   went onto the shared full-bleed one. .fg-hero--compact hides .fg-hero__intro,
   so they need somewhere real to live rather than sitting in markup that never
   renders. Two columns so the block reads as one band rather than a paragraph
   with a list dangling under it. */
.fg-roof-lantern-lede {
  padding: clamp(1.6rem, 3.2vw, 2.6rem) 0 0;
}

.fg-roof-lantern-lede .container {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  gap: clamp(1rem, 2.4vw, 2rem);
  align-items: start;
}

.fg-roof-lantern-lede p {
  margin: 0;
  max-width: 60ch;
  color: var(--color-muted);
  font-size: 1.05rem;
}

@media (max-width: 860px) {
  .fg-roof-lantern-lede .container {
    grid-template-columns: minmax(0, 1fr);
  }
}

.fg-roof-lantern-hero__media {
  position: relative;
  width: min(100%, 600px);
  min-height: 0;
  aspect-ratio: 4 / 3;
  margin: 0;
  justify-self: end;
  overflow: hidden;
  border-radius: 8px;
  background: var(--color-steel);
}

.fg-roof-lantern-hero__media::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 35%;
  background: linear-gradient(transparent, rgba(10, 34, 38, 0.72));
  content: '';
}

.fg-roof-lantern-hero__media img,
.fg-roof-lantern-intro__media img,
.fg-roof-lantern-options figure img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.fg-roof-lantern-hero__media figcaption {
  position: absolute;
  z-index: 1;
  right: 1.25rem;
  bottom: 1.15rem;
  left: 1.25rem;
  display: inline-block;
  right: auto;
  left: 1.25rem;
  padding: 0.55rem 0.7rem;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.9);
  color: var(--color-ink);
  font-size: var(--fg-text-xs);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.fg-roof-lantern-brief {
  padding-bottom: clamp(1.75rem, 3.5vh, 2.5rem);
}

.fg-roof-lantern-brief__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  overflow: hidden;
  border: 1px solid rgba(15, 49, 54, 0.15);
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.62);
}

.fg-roof-lantern-brief p {
  display: grid;
  gap: var(--fg-space-2);
  padding: 1rem 1.1rem;
  margin: 0;
  border-right: 1px solid rgba(15, 49, 54, 0.12);
}

.fg-roof-lantern-brief p:last-child {
  border-right: 0;
}

.fg-roof-lantern-brief strong {
  color: var(--color-ink);
  font-size: 0.95rem;
}

.fg-roof-lantern-brief span {
  color: var(--color-muted);
  font-size: var(--fg-text-sm);
  line-height: 1.45;
}

.fg-roof-lantern-configurations {
  padding: clamp(2rem, 4.5vh, 3rem) 0;
}

.fg-roof-lantern-configurations__heading {
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1fr);
  column-gap: clamp(2rem, 6vw, 7rem);
  align-items: end;
  margin-bottom: 1rem;
}

.fg-roof-lantern-configurations__heading .eyebrow {
  grid-column: 1 / -1;
}

.fg-roof-lantern-configurations__heading h2 {
  max-width: 16ch;
  margin-bottom: 0;
  color: var(--color-ink);
  font-size: clamp(1.45rem, 2.2vw, 2rem);
  line-height: 1.08;
}

.fg-roof-lantern-configurations__heading p:not(.eyebrow) {
  max-width: 54ch;
  margin-bottom: 0.2rem;
  color: var(--color-muted);
  line-height: 1.58;
}

/* The S1 layouts reuse the composite door wall: same `.fg-cd3-wall__viewport`,
   same track, same drift controller in main.js, so the two cannot drift apart.
   Only the card differs. A lantern render is a wide product shot floating on
   white, so it is contained on a soft panel with the label underneath rather
   than cover-cropped under a dark gradient the way a door photograph is. */
.fg-lantern-card {
  position: relative;
  flex: 0 0 auto;
  width: 300px;
  overflow: hidden;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 14px 34px rgba(2, 43, 53, 0.13);
}

.fg-lantern-card img {
  display: block;
  width: 100%;
  height: 180px;
  padding: 0.55rem 0.7rem 0;
  background: linear-gradient(180deg, #eef4f3, #ffffff);
  object-fit: contain;
}

.fg-lantern-card__label {
  display: grid;
  gap: 0.12rem;
  padding: 0.7rem 0.9rem 0.8rem;
  border-top: 1px solid rgba(2, 43, 53, 0.1);
}

.fg-lantern-card__label strong {
  color: var(--color-steel);
  font-size: 0.85rem;
  font-weight: 800;
  line-height: 1.25;
}

.fg-lantern-card__label small {
  color: rgba(2, 43, 53, 0.6);
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.fg-roof-lantern-views {
  padding: clamp(2rem, 4.5vh, 2.75rem) 0;
}

.fg-roof-lantern-views__heading {
  display: grid;
  grid-template-columns: minmax(0, 0.7fr) minmax(0, 1fr);
  column-gap: clamp(2rem, 6vw, 7rem);
  align-items: end;
  margin-bottom: 1rem;
}

.fg-roof-lantern-views__heading .eyebrow {
  grid-column: 1 / -1;
}

.fg-roof-lantern-views__heading h2 {
  max-width: 13ch;
  margin-bottom: 0;
  color: var(--color-ink);
  font-size: clamp(1.45rem, 2.2vw, 2rem);
  line-height: 1.08;
}

.fg-roof-lantern-views__heading p:not(.eyebrow) {
  max-width: 48ch;
  margin-bottom: 0.2rem;
  color: var(--color-muted);
  line-height: 1.65;
}

.fg-roof-lantern-views__grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--fg-space-4);
}

.fg-roof-lantern-views figure {
  position: relative;
  aspect-ratio: 3 / 2;
  min-height: 0;
  margin: 0;
  overflow: hidden;
  border-radius: 8px;
  background: var(--color-soft);
}

.fg-roof-lantern-views img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.fg-roof-lantern-views figcaption {
  position: absolute;
  right: 0.75rem;
  bottom: 0.75rem;
  left: 0.75rem;
  width: fit-content;
  padding: 0.45rem 0.6rem;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.9);
  color: var(--color-ink);
  font-size: var(--fg-text-2xs);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.fg-roof-lantern-intro,
.fg-roof-lantern-system,
.fg-roof-lantern-options,
.fg-roof-lantern-enquiry {
  padding: clamp(2rem, 4.5vh, 3rem) 0;
}

.fg-roof-lantern-intro__grid {
  grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
}

.fg-roof-lantern-intro__media {
  height: clamp(320px, 50vh, 460px);
  margin: 0;
  border-radius: 8px;
  overflow: hidden;
}

.fg-roof-lantern-intro__copy h2,
.fg-roof-lantern-system__copy h2,
.fg-roof-lantern-enquiry h2 {
  max-width: 16ch;
  margin-bottom: 1.2rem;
  font-size: clamp(1.45rem, 2.2vw, 2rem);
  line-height: 1.08;
}

.fg-roof-lantern-intro__copy > p:not(.eyebrow),
.fg-roof-lantern-system__copy > p:not(.eyebrow),
.fg-roof-lantern-enquiry__copy > p:not(.eyebrow) {
  max-width: 54ch;
  color: var(--color-muted);
  line-height: 1.7;
}

.fg-roof-lantern-intro__steps {
  display: grid;
  gap: 0.9rem;
  padding: 0;
  margin: 1.25rem 0 0;
  list-style: none;
  counter-reset: steps;
}

.fg-roof-lantern-intro__steps li {
  display: grid;
