}

.fg-roof-lantern-form input:focus,
.fg-heritage-door-form input:focus,
.fg-roof-lantern-form select:focus,
.fg-heritage-door-form select:focus,
.fg-roof-lantern-form textarea:focus,
.fg-heritage-door-form textarea:focus {
