@media (min-width: 700px) {
  .fg-roof-lantern-intro__grid {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  }

  .fg-roof-lantern-enquiry__grid {
    grid-template-columns: minmax(0, 0.65fr) minmax(0, 1.35fr);
    gap: clamp(1.5rem, 3vw, 3rem);
  }

  .fg-roof-lantern-form .fg-enquiry-form__body-head,
  .fg-heritage-door-form .fg-enquiry-form__body-head {
    display: none;
  }

  .fg-roof-lantern-form .fg-enquiry-form__body,
  .fg-heritage-door-form .fg-enquiry-form__body,
  .fg-roof-lantern-form .fg-enquiry-form__step,
  .fg-heritage-door-form .fg-enquiry-form__step {
    gap: 0.65rem;
  }

  .fg-roof-lantern-form .fg-enquiry-form__row,
  .fg-heritage-door-form .fg-enquiry-form__row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.65rem;
  }

  .fg-roof-lantern-form label,
  .fg-heritage-door-form label {
    font-size: 0.9rem;
  }

  .fg-roof-lantern-form input:not([type="checkbox"]),
  .fg-heritage-door-form input:not([type="checkbox"]),
  .fg-roof-lantern-form select,
  .fg-heritage-door-form select {
    min-height: 44px;
    padding-block: 0.55rem;
  }

  .fg-roof-lantern-form textarea,
  .fg-heritage-door-form textarea {
    min-height: 140px;
  }

  .fg-roof-lantern-form .fg-enquiry-form__step:last-child,
  .fg-heritage-door-form .fg-enquiry-form__step:last-child {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
    grid-template-rows: auto auto 1fr;
    column-gap: 0.8rem;
  }

  .fg-roof-lantern-form .fg-enquiry-form__message,
  .fg-heritage-door-form .fg-enquiry-form__message {
    grid-column: 1;
    grid-row: 1 / 4;
  }

  .fg-roof-lantern-form .fg-enquiry-form__step:last-child > label:not(.fg-enquiry-form__message, .fg-enquiry-form__consent),
  .fg-heritage-door-form .fg-enquiry-form__step:last-child > label:not(.fg-enquiry-form__message, .fg-enquiry-form__consent) {
    grid-column: 2;
    grid-row: 1;
  }

  .fg-roof-lantern-form .fg-enquiry-form__consent,
  .fg-heritage-door-form .fg-enquiry-form__consent {
    grid-column: 2;
    grid-row: 2;
    padding: 0.65rem;
  }

  .fg-roof-lantern-form .fg-enquiry-form__footer,
  .fg-heritage-door-form .fg-enquiry-form__footer {
    grid-column: 2;
    grid-row: 3;
    display: grid;
    gap: 0.45rem;
  }

  .fg-roof-lantern-form .fg-enquiry-form__footer > .button,
  .fg-heritage-door-form .fg-enquiry-form__footer > .button {
    min-width: 0;
    min-height: 48px;
  }

  .fg-roof-lantern-form .fg-enquiry-form__footer > small,
  .fg-heritage-door-form .fg-enquiry-form__footer > small {
    max-width: none;
  }
}

.fg-roof-lantern-page .fg-review-showcase {
  padding-top: clamp(2.5rem, 5vw, 5rem);
}

@media (max-width: 860px) {
  .fg-roof-lantern-hero,
  .fg-roof-lantern-intro,
  .fg-roof-lantern-options,
  .fg-roof-lantern-enquiry {
    padding: 2.5rem 0;
  }

  .fg-roof-lantern-system {
    padding: 2rem 0;
  }

  .fg-roof-lantern-hero__grid,
  .fg-roof-lantern-intro__grid,
  .fg-roof-lantern-enquiry__grid {
    grid-template-columns: 1fr;
    gap: var(--fg-space-8);
  }

  .fg-roof-lantern-system__grid {
    grid-template-columns: 1fr;
    gap: var(--fg-space-5);
  }

  .fg-roof-lantern-hero__copy {
    padding: 0;
  }

  .fg-roof-lantern-hero h1 {
    max-width: 12ch;
  }

  .fg-roof-lantern-hero__media {
    width: min(100%, 430px);
    min-height: 0;
    aspect-ratio: 4 / 3;
    justify-self: start;
  }

  .fg-roof-lantern-brief__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .fg-roof-lantern-brief p:nth-child(2) {
    border-right: 0;
  }

  .fg-roof-lantern-brief p:nth-child(-n + 2) {
    border-bottom: 1px solid rgba(15, 49, 54, 0.12);
  }

  .fg-roof-lantern-configurations__heading {
    grid-template-columns: 1fr;
    gap: 0.9rem;
  }

  .fg-roof-lantern-views__heading {
    grid-template-columns: 1fr;
    gap: 0.9rem;
  }

  .fg-roof-lantern-options__heading {
    grid-template-columns: 1fr;
    gap: 0.9rem;
  }

  .fg-roof-lantern-views__grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .fg-roof-lantern-intro__media {
    height: auto;
    aspect-ratio: 1.1;
  }

  .fg-roof-lantern-system__corner {
    transform: none;
  }

  .fg-roof-lantern-enquiry__form {
    padding: 1rem;
  }
}

@media (max-width: 560px) {
  .fg-roof-lantern-hero {
    padding: 1.75rem 0;
  }

  .fg-roof-lantern-hero h1 {
    font-size: clamp(2.35rem, 11vw, 3rem);
  }

  .fg-roof-lantern-hero__actions {
    display: grid;
    gap: 0.85rem;
  }

  .fg-roof-lantern-hero__actions .button {
    width: 100%;
  }

  .fg-roof-lantern-hero__reassurance {
    display: none;
  }

  .fg-roof-lantern-hero__media {
    aspect-ratio: 16 / 9;
  }

  .fg-roof-lantern-brief__grid {
    grid-template-columns: 1fr;
  }

  .fg-roof-lantern-views {
    padding-bottom: 3.25rem;
  }

  .fg-roof-lantern-configurations {
    padding: 2.25rem 0;
  }

  .fg-roof-lantern-views__grid {
    grid-template-columns: none;
    grid-auto-flow: column;
    grid-auto-columns: 84%;
    gap: 0.65rem;
    padding-bottom: 0.65rem;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    scrollbar-width: thin;
  }

  .fg-roof-lantern-views figure {
    scroll-snap-align: start;
  }

  .fg-roof-lantern-brief p,
  .fg-roof-lantern-brief p:nth-child(2) {
    border-right: 0;
    border-bottom: 1px solid rgba(15, 49, 54, 0.12);
  }

  .fg-roof-lantern-brief p:last-child {
    border-bottom: 0;
  }

  .fg-roof-lantern-intro__copy h2,
  .fg-roof-lantern-system__copy h2,
  .fg-roof-lantern-options__heading h2,
  .fg-roof-lantern-enquiry h2 {
    max-width: 13ch;
  }

  .fg-roof-lantern-system__points div {
    grid-template-columns: 1fr;
    gap: 0.35rem;
  }

  .fg-roof-lantern-system__visuals {
    grid-template-columns: minmax(0, 1fr) minmax(100px, 0.6fr);
    gap: 0.7rem;
  }

  .fg-roof-lantern-options__grid {
    grid-template-columns: 1fr;
  }
}

@media (min-width: 700px) and (max-width: 860px) {
  .fg-roof-lantern-intro__grid {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  }

  .fg-roof-lantern-enquiry__grid {
    grid-template-columns: minmax(0, 0.65fr) minmax(0, 1.35fr);
    gap: var(--fg-space-6);
  }
}

