}

.fg-fensa-hero {
  padding: clamp(2.8rem, 5vw, 4.4rem) 0 clamp(3.2rem, 5vw, 4.8rem);
}

.fg-fensa-hero__grid,
.fg-fensa-enquiry__grid {
  display: grid;
