  align-items: center;
  gap: clamp(2rem, 4vw, 4rem);
}

.fg-flat-rooflight-hero__grid {
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
}

.fg-flat-rooflight-hero__copy {
  padding: 0.75rem 0;
}

.fg-flat-rooflight-hero h1 {
  max-width: 12ch;
  margin-bottom: 1rem;
  font-size: clamp(2.5rem, 3.6vw, 3.6rem);
  line-height: 0.98;
}

.fg-flat-rooflight-hero__lead {
  max-width: 55ch;
  color: var(--color-muted);
  font-size: clamp(1.05rem, 1.3vw, 1.22rem);
  line-height: 1.58;
}

.fg-flat-rooflight-hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--fg-space-4);
  margin: 1.5rem 0 1.25rem;
}

.fg-flat-rooflight-hero__call {
  color: var(--color-ink);
  font-weight: 700;
  text-decoration: none;
}

.fg-flat-rooflight-hero__call:hover {
  color: var(--color-accent-dark);
}

.fg-flat-rooflight-hero__reassurance,
.fg-flat-rooflight-enquiry__copy ul {
  display: grid;
  gap: 0.6rem;
  padding: 0;
  margin: 0;
  list-style: none;
}

.fg-flat-rooflight-hero__reassurance li,
.fg-flat-rooflight-enquiry__copy li {
  position: relative;
  padding-left: 1.45rem;
  color: var(--color-muted);
}

.fg-flat-rooflight-hero__reassurance li::before,
.fg-flat-rooflight-enquiry__copy li::before {
  position: absolute;
  top: 0.45em;
  left: 0;
  width: 0.55rem;
  height: 0.55rem;
  border-radius: 50%;
