.fg-flat-rooflight-hero__media {
  position: relative;
  width: min(100%, 600px);
  min-height: 0;
  aspect-ratio: 4 / 3;
  margin: 0;
  justify-self: end;
  overflow: hidden;
  border-radius: 8px;
  background: var(--color-soft);
}

.fg-flat-rooflight-hero__media::after {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 35%;
  background: linear-gradient(transparent, rgba(10, 34, 38, 0.72));
