    grid-template-areas: "controls preview";
    grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  }

  .fg-composite-choice-preview,
  .fg-composite-choice-selector--glass .fg-composite-choice-preview {
