}

@media (max-width: 1180px) {
  .fg-cd3-colour__swatches {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .fg-cd3-collections__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 860px) {
  /* The wall stops drifting and becomes a normal swipe rail with the clone
     removed, so touch scrolling never fights a running animation. */
  .fg-cd3-wall__track {
    gap: 0.6rem;
    width: auto;
    padding: 0.35rem 1rem;
    animation: none;
    scroll-snap-type: x proximity;
  }

  .fg-cd3-wall__viewport {
    overflow-x: auto;
    -webkit-mask-image: none;
    mask-image: none;
    -webkit-overflow-scrolling: touch;
  }

  .fg-cd3-door {
    width: 148px;
    scroll-snap-align: start;
  }

  .fg-cd3-door img {
    height: 360px;
  }

  .fg-cd3-door.is-clone,
  .fg-lantern-card.is-clone {
    display: none;
  }

  .fg-lantern-card {
    width: 250px;
    scroll-snap-align: start;
  }

  .fg-lantern-card img {
    height: 150px;
  }

  /* Preview leads on a phone, then the swatches under it. */
  .fg-cd3-colour__layout {
    grid-template-columns: 1fr;
  }

  .fg-cd3-colour__preview {
    order: -1;
    position: static;
  }

  .fg-cd3-colour__swatches {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  /* Collections become an image-led swipe carousel, matching how the homepage
     presents the product range on a phone. Stacking six cards made the section
     about 1,400px tall and nobody scrolled it. */
  .fg-cd3-collections__cue {
    display: block;
    margin: 0 0 0.9rem;
    color: rgba(2, 43, 53, 0.6);
    font-size: 0.9rem;
  }

  .fg-cd3-collections__carousel {
    position: relative;
    margin-inline: calc(50% - 50vw);
  }

  .fg-cd3-collections__grid {
    display: flex;
    grid-template-columns: none;
    gap: 0.9rem;
    padding: 0.25rem max(1rem, calc((100vw - var(--container)) / 2)) 0.25rem;
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scroll-padding-inline: max(1rem, calc((100vw - var(--container)) / 2));
    scroll-snap-type: inline mandatory;
    scrollbar-width: none;
    align-items: stretch;
    -webkit-overflow-scrolling: touch;
  }

  .fg-cd3-collections__grid::-webkit-scrollbar {
    display: none;
  }

  /* Every door is a different shape (0.406 to 0.453 wide-to-tall), so a fixed
     card either crops one or leaves the row ragged. The image area is a fixed
     portrait panel and each door is contained inside it, which lands them all
     at the same height like a proper lineup.

     Both rows are a fixed height rather than content-driven: the caption box
     is the same size on every card whatever the copy runs to, so the doors
     stay level without the track having to stretch to the longest paragraph.
     The caption overlaps the base of the image panel to buy that height back,
     which works because the figure reserves the overlap as bottom padding, so
     the caption rides over the tint and never over the door itself. */
  .fg-cd3-collection {
    --fg-card-caption: 8.5rem;
    --fg-card-overlap: 1.6rem;

    display: grid;
    grid-template-columns: none;
    grid-template-rows: auto var(--fg-card-caption);
    flex: 0 0 min(66vw, 280px);
    min-height: 0;
    overflow: hidden;
    border: 1px solid rgba(2, 43, 53, 0.12);
    border-radius: 14px;
    background: #fff;
    box-shadow: 0 18px 44px rgba(2, 43, 53, 0.1);
    scroll-snap-align: start;
    scroll-snap-stop: always;
  }

  .fg-cd3-collection::after {
    display: none;
  }

  .fg-cd3-collection__img {
    position: static;
    z-index: auto;
    inset: auto;
    height: auto;
    aspect-ratio: 100 / 150;
    padding: 0.9rem 0.9rem calc(var(--fg-card-overlap) + 0.4rem);
    background: linear-gradient(180deg, #f5f8f7 0%, #e6edeb 100%);
  }

  .fg-cd3-collection__img img {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: contain;
    object-position: center bottom;
    filter: drop-shadow(0 10px 18px rgba(2, 43, 53, 0.16));
  }

  .fg-cd3-collection__body {
    position: static;
    z-index: 2;
    display: grid;
    align-content: start;
    gap: 0.2rem;
    height: calc(var(--fg-card-caption) + var(--fg-card-overlap));
    margin-top: calc(var(--fg-card-overlap) * -1);
    padding: 0.75rem 1rem 0.9rem;
    overflow: hidden;
    border-radius: 14px 14px 0 0;
    background: #fff;
  }

  .fg-cd3-collection__body h3 {
    font-size: 1.1rem;
  }

  /* The box is fixed, so the paragraph is clamped to what fits rather than
     being allowed to spill out of the bottom of the card. */
  .fg-cd3-collection__body > p {
    display: -webkit-box;
    overflow: hidden;
    font-size: 0.82rem;
    line-height: 1.4;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 4;
  }

  .fg-cd3-collection__slab {
    -webkit-line-clamp: 2;
  }

  .fg-cd3-collections__dots {
    display: flex;
    gap: 0.4rem;
    align-items: center;
    justify-content: center;
    padding: 0.9rem 0 0;
  }

  .fg-cd3-collections__dots span {
    display: block;
    width: 8px;
    height: 8px;
    border-radius: 999px;
    background: rgba(2, 43, 53, 0.24);
    transition: width 180ms ease, background 180ms ease;
  }

  .fg-cd3-collections__dots span.is-active {
    width: 20px;
    background: var(--color-accent);
  }

  .fg-cd3-security__inner,
  .fg-cd3-security__points,
  .fg-cd3-security__lead {
    grid-template-columns: 1fr;
  }

  .fg-cd3-security__lead {
    justify-items: start;
  }

  .fg-cd3-anatomy__explorer {
    grid-template-columns: 1fr;
    padding: 1rem;
  }

  /* The cutaway is a peeled-back corner: the meaning is at the top, where the
     skin lifts off the core and the timber stile. Stacked, a band crop shows
     that at full width instead of 357px of repeated door face below it. */
  /* Capped, or the band grows with the viewport and by tablet width it is a
     400px close-up of one corner of the illustration. */
  .fg-cd3-anatomy__media {
    width: 100%;
    aspect-ratio: 16 / 9;
    max-height: 260px;
  }

  .fg-cd3-anatomy__media img {
    object-position: center 22%;
  }

  .fg-cd3-anatomy__stats {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .fg-cd3-anatomy__stats > div + div {
    border-left: 0;
  }

  .fg-cd3-anatomy__stats > div:nth-child(2n) {
    border-left: 1px solid rgba(2, 43, 53, 0.1);
  }

  .fg-cd3-anatomy__stats > div:nth-child(n + 3) {
    border-top: 1px solid rgba(2, 43, 53, 0.1);
  }

  .fg-cd3-mosaic {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-auto-rows: 168px;
  }

  .fg-cd3-tile.is-anchor {
    grid-column: span 1;
    grid-row: span 1;
  }

  .fg-cd3-types__panel {
    grid-template-columns: 1fr;
  }

  .fg-cd3-types__img img {
    min-height: 220px;
  }
}

