  .fg-cd-v2-selector__controls,
  .fg-cd-v2-hardware__controls { padding: 1.1rem; }

  .fg-cd-v2-selector__controls > p:not(.eyebrow),
  .fg-cd-v2-hardware__controls > p:not(.eyebrow) {
